{
  "name": "Blocky Runner",
  "description": "A high-speed FPV infinite runner with a voxel aesthetic. Collect gold, avoid TNT, and run as far as you can!"
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BlockType {
  GRASS = 'GRASS',
  DIRT = 'DIRT',
  STONE = 'STONE',
  WOOD = 'WOOD',
  LEAVES = 'LEAVES',
  GOLD = 'GOLD', // Collectible
  TNT = 'TNT',   // Obstacle
  LAVA = 'LAVA'
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Entity {
  id: string;
  type: BlockType;
  position: Point3D;
  size: number;
  collected?: boolean;
  rotation?: number; // For gold blocks
}

export interface GameState {
  isPlaying: boolean;
  score: number;
  distance: number;
  speed: number;
  lives: number;
  gameOver: boolean;
}

export interface PlayerState {
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
}

import { BlockType } from './types';

// World Configuration
export const CHUNK_SIZE = 20; // Number of blocks visible
export const BLOCK_SIZE = 100; // Visual scale unit
export const LANE_WIDTH = 1.2; // Width of lanes in world units
export const GRAVITY = 0.04;
export const JUMP_FORCE = 0.6;
export const MOVE_SPEED = 0.15; // Lateral speed
export const RUN_SPEED_BASE = 0.3;
export const RUN_SPEED_MAX = 0.8;
export const ACCELERATION = 0.0001;

// Colors for Voxel Rendering
export const COLORS: Record<BlockType, { top: string; side: string; front: string }> = {
  [BlockType.GRASS]: { top: '#5b8d26', side: '#4b701d', front: '#4b701d' },
  [BlockType.DIRT]: { top: '#6d4f33', side: '#543d28', front: '#543d28' },
  [BlockType.STONE]: { top: '#9e9e9e', side: '#757575', front: '#757575' },
  [BlockType.WOOD]: { top: '#8f6946', side: '#6b4e33', front: '#6b4e33' },
  [BlockType.LEAVES]: { top: '#3ea329', side: '#2d7a1e', front: '#2d7a1e' },
  [BlockType.GOLD]: { top: '#ffe600', side: '#d4af37', front: '#d4af37' },
  [BlockType.TNT]: { top: '#db3625', side: '#ffffff', front: '#db3625' }, // TNT has a specific look we might approximate
  [BlockType.LAVA]: { top: '#cf1020', side: '#cf1020', front: '#ff4500' },
};

export const SKY_COLOR = '#87CEEB';
export const FOG_COLOR = '#87CEEB';

import { BlockType, Entity, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  RUN_SPEED_BASE, 
  RUN_SPEED_MAX, 
  ACCELERATION, 
  LANE_WIDTH 
} from '../constants';

export class GameEngine {
  public entities: Entity[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false
  };

  private lastGenZ = 10;
  private currentSpeed = RUN_SPEED_BASE;
  private score = 0;
  private lives = 3;

  constructor() {
    this.reset();
  }

  reset() {
    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false
    };
    this.entities = [];
    this.currentSpeed = RUN_SPEED_BASE;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;

    // Initial ground generation
    for (let z = 0; z < 20; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean }, deltaTime: number) {
    // 1. Move Player Forward
    this.currentSpeed = Math.min(this.currentSpeed + ACCELERATION, RUN_SPEED_MAX);
    this.player.position.z += this.currentSpeed;

    // 2. Lateral Movement (Strafe)
    // Smoothly interpolate towards target lane or just move raw
    // Let's use raw movement with limits for a "Minecraft" feel
    const moveSpeed = 0.15;
    if (input.left) this.player.position.x -= moveSpeed;
    if (input.right) this.player.position.x += moveSpeed;

    // Clamp X
    if (this.player.position.x < -LANE_WIDTH * 1.5) this.player.position.x = -LANE_WIDTH * 1.5;
    if (this.player.position.x > LANE_WIDTH * 1.5) this.player.position.x = LANE_WIDTH * 1.5;

    // 3. Jump & Gravity
    if (input.jump && !this.player.isJumping) {
      this.player.velocity.y = JUMP_FORCE;
      this.player.isJumping = true;
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision (Simple floor at y=0)
    // In a real voxel engine we'd check block height, but here we assume ground is 0 unless on a block.
    // We will do simple AABB vs Blocks later, for now floor is 0.
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
    }

    // 4. World Generation
    // Generate ahead
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 5. Collision Detection
    this.checkCollisions();
  }

  private generateSlice(z: number) {
    // Always ground
    for (let x = -2; x <= 2; x++) {
       // Only draw the 3 main lanes usually, but let's make it 5 wide for visuals
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS, // Pattern
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    // Random Obstacles & Collectibles (only after z > 10)
    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; // -1, 0, 1
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Avoid blocking all lanes logic would go here (simplified for now)

      if (rand < 0.15) {
        // Obstacle: TNT or Stone
        const type = Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE;
        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Sometimes stack them
        if (Math.random() > 0.7) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.6 && rand < 0.8) {
        // Collectible: Gold
        // Often in a row
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z }, // Float slightly
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      // Simple AABB
      // Entities are centered at position.
      // Player is centered at position.

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
    } else if (entity.type === BlockType.TNT || entity.type === BlockType.STONE || entity.type === BlockType.LAVA) {
      // Hit obstacle
      // For now, simple game over or slow down?
      // Let's remove lives.
      this.lives -= 1;
      // Push player back/invulnerable or just remove entity to prevent multi-hit
      entity.collected = true; // effectively removes it from collision

      if (this.lives <= 0) {
        // Game Over handled by App checking state
      }
    }
  }

  public getState() {
    return {
      entities: this.entities,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed
    };
  }
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean } };
}

const FOV = 400; // Field of view scale factor

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);

  // Helper to project 3D point to 2D screen space
  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number) => {
    // Relative to camera
    const rx = p.x - camX;
    const ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0) return null; // Behind camera

    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale); // Invert Y for canvas

    return { x: x2d, y: y2d, scale };
  }, []);

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, 
    width: number, height: number
  ) => {
    if (entity.collected) return;

    // Entity position is center. Get corners.
    const hs = entity.size / 2; // Half scale
    const { x, y, z } = entity.position;

    // Rotation for gold
    let finalX = x; 
    let finalZ = z;
    // (Skipping rotation matrix for performance/simplicity, gold just floats)

    // Vertices relative to center
    // We only need to draw Visible faces.
    // 1. Top face (if y < camY mostly, or just always draw if not completely covered)
    // 2. Front face (always, as we run towards it)
    // 3. Side face (depending on x vs camX)

    // Determine color
    const colors = COLORS[entity.type] || COLORS[BlockType.DIRT];

    // Project Center to check culling roughly
    const projC = project({x, y, z}, camX, camY, camZ, width, height);
    if (!projC) return; // Behind

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, // Front Top Left
      ftr: {x: x + hs, y: y + hs, z: z - hs}, // Front Top Right
      fb: {x: x - hs, y: y - hs, z: z - hs}, // Front Bottom Left
      fbr: {x: x + hs, y: y - hs, z: z - hs}, // Front Bottom Right

      bt: {x: x - hs, y: y + hs, z: z + hs}, // Back Top Left
      btr: {x: x + hs, y: y + hs, z: z + hs}, // Back Top Right
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height),
        ftr: project(v.ftr, camX, camY, camZ, width, height),
        fb: project(v.fb, camX, camY, camZ, width, height),
        fbr: project(v.fbr, camX, camY, camZ, width, height),
        bt: project(v.bt, camX, camY, camZ, width, height),
        btr: project(v.btr, camX, camY, camZ, width, height),
    };

    // If front face is behind camera (z-hs < camZ), don't draw front face? 
    // Simplified: Just check if any point is null, if so, skip (clipping is hard in 2D canvas)
    // To prevent popping, we usually need proper clipping. 
    // Hack: If projected points are missing, don't draw. This causes popping at edges of screen.
    // Better Hack: Render distance handles far z. Near z is the issue. 
    // If z is too close, don't draw.
    if (z - camZ < 0.5) return; 

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    // --- Draw Front Face ---
    ctx.fillStyle = colors.front;
    // Add border for "voxel" look
    ctx.strokeStyle = "rgba(0,0,0,0.2)"; 
    ctx.lineWidth = 1;

    ctx.beginPath();
    ctx.moveTo(p.ft.x, p.ft.y);
    ctx.lineTo(p.ftr.x, p.ftr.y);
    ctx.lineTo(p.fbr.x, p.fbr.y);
    ctx.lineTo(p.fb.x, p.fb.y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // --- Draw Top Face ---
    // Only if below eye level roughly, or just always draw it on top of front for this perspective
    ctx.fillStyle = colors.top;
    ctx.beginPath();
    ctx.moveTo(p.bt.x, p.bt.y);
    ctx.lineTo(p.btr.x, p.btr.y);
    ctx.lineTo(p.ftr.x, p.ftr.y);
    ctx.lineTo(p.ft.x, p.ft.y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // --- Draw Side Face ---
    // If x < camX, we see Right side. If x > camX, we see Left side.
    if (x < camX) {
        // Draw Right Side (at x + hs)
        ctx.fillStyle = colors.side;
        ctx.beginPath();
        ctx.moveTo(p.ftr.x, p.ftr.y); // Front Top Right
        ctx.lineTo(p.btr.x, p.btr.y); // Back Top Right
        // We need Back Bottom Right ideally, but we can approximate or calculate it
        // Let's just calculate back bottom right
        const bbr = project({x: x + hs, y: y - hs, z: z + hs}, camX, camY, camZ, width, height);
        if (bbr) {
            ctx.lineTo(bbr.x, bbr.y);
            ctx.lineTo(p.fbr.x, p.fbr.y);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
        }
    } else {
        // Draw Left Side (at x - hs)
        ctx.fillStyle = colors.side;
        ctx.beginPath();
        ctx.moveTo(p.bt.x, p.bt.y); // Back Top Left
        ctx.lineTo(p.ft.x, p.ft.y); // Front Top Left
        ctx.lineTo(p.fb.x, p.fb.y); // Front Bottom Left
        // Back Bottom Left
        const bbl = project({x: x - hs, y: y - hs, z: z + hs}, camX, camY, camZ, width, height);
        if (bbl) {
            ctx.lineTo(bbl.x, bbl.y);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
        }
    }

  }, [project]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Update Game Logic
    engine.update(inputState.current, 16);
    const state = engine.getState();

    // Update UI Elements directly to avoid React rerender loop
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (state.lives <= 0) {
      onGameOver(state.score);
      return; 
    }

    // --- RENDER ---
    const width = canvas.width;
    const height = canvas.height;

    // Clear Screen & Draw Sky
    ctx.fillStyle = SKY_COLOR;
    ctx.fillRect(0, 0, width, height);

    // Draw Ground Gradient (Fake horizon)
    const horizonY = height / 2;
    ctx.fillStyle = '#4a6b22'; // Darker grass for distance
    ctx.fillRect(0, horizonY, width, height/2);

    // Camera setup
    // Camera follows player, but smoothed or fixed offset
    const camX = state.player.position.x;
    const camY = state.player.position.y + 1.6; // Eye height
    const camZ = state.player.position.z - 0.5; // Slightly behind head or inside? 
    // Actually, FPV means cam is AT player eyes. 
    // Player body is usually not rendered in simple FPV, or just hands.
    // Let's put camera exactly at player head.

    // Sort entities by Z (Painter's Algorithm: Far to Near)
    // We strictly sort descending Z.
    // Note: This is imperfect for complex overlap but fine for a runner where Z dominates.
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    // Draw Entities
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, width, height);
    }

    // Motion Lines (Speed Effect)
    if (state.speed > 0.4) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 5; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x - (x-width/2)*0.1, y - (y-height/2)*0.1); // Radiate from center
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 10, height/2);
    ctx.lineTo(width/2 + 10, height/2);
    ctx.moveTo(width/2, height/2 - 10);
    ctx.lineTo(width/2, height/2 + 10);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />

      {/* HUD Layer - Directly updated via refs for performance */}
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-md select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef}>SCORE: 0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>

      <div className="absolute top-4 right-4 text-white/50 text-sm font-mono select-none">
        WASD / Arrows to Move • SPACE to Jump
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { GameEngine } from './services/engine';

enum AppState {
  MENU,
  PLAYING,
  GAME_OVER
}

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.MENU);
  const [finalScore, setFinalScore] = useState(0);
  const engineRef = useRef<GameEngine>(new GameEngine());

  // We store input in a Ref so the game loop reads it without triggering React renders
  const inputState = useRef({
    left: false,
    right: false,
    jump: false
  });

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (appState !== AppState.PLAYING) return;

      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = true;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = true;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = true;
          break;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = false;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = false;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = false;
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [appState]);

  const startGame = () => {
    engineRef.current.reset();
    inputState.current = { left: false, right: false, jump: false };
    setAppState(AppState.PLAYING);
  };

  const handleGameOver = (score: number) => {
    setFinalScore(score);
    setAppState(AppState.GAME_OVER);
  };

  return (
    <div className="w-full h-screen bg-neutral-900 flex flex-col items-center justify-center">
      {appState === AppState.MENU && (
        <div className="z-10 text-center p-8 bg-black/60 backdrop-blur-sm border-4 border-green-600 rounded-lg shadow-[0_0_20px_rgba(0,255,0,0.5)]">
          <h1 className="text-6xl mb-4 text-green-400 font-bold tracking-tighter drop-shadow-md">BLOCKY RUNNER</h1>
          <p className="text-xl text-gray-300 mb-8 font-mono">Run fast. Collect Gold. Don't blow up.</p>
          <button 
            onClick={startGame}
            className="px-8 py-4 bg-green-600 hover:bg-green-500 text-white text-2xl font-bold border-b-4 border-green-800 active:border-b-0 active:translate-y-1 transition-all"
          >
            START RUN
          </button>
        </div>
      )}

      {appState === AppState.PLAYING && (
        <GameCanvas 
          engine={engineRef.current} 
          onGameOver={handleGameOver} 
          inputState={inputState}
        />
      )}

      {appState === AppState.GAME_OVER && (
        <div className="z-10 text-center p-8 bg-red-900/80 backdrop-blur-sm border-4 border-red-600 rounded-lg shadow-[0_0_30px_rgba(255,0,0,0.5)]">
          <h2 className="text-5xl text-red-200 mb-2 font-bold">GAME OVER</h2>
          <div className="text-3xl text-yellow-400 mb-8">Score: {finalScore}</div>
          <button 
            onClick={startGame}
            className="px-8 py-4 bg-gray-100 hover:bg-white text-black text-xl font-bold border-b-4 border-gray-400 active:border-b-0 active:translate-y-1 transition-all"
          >
            TRY AGAIN
          </button>
        </div>
      )}

      {/* Background decoration for menu */}
      {appState !== AppState.PLAYING && (
         <div className="absolute inset-0 -z-10 overflow-hidden opacity-30">
            <div className="absolute w-full h-full bg-[linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111),linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111)] bg-[length:40px_40px] bg-[position:0_0,20px_20px] bg-neutral-800" />
         </div>
      )}
    </div>
  );
}

import { BlockType } from './types';

// World Configuration
export const CHUNK_SIZE = 20; 
export const BLOCK_SIZE = 100;
export const LANE_WIDTH = 1.2;
export const GRAVITY = 0.045;
export const JUMP_FORCE = 0.65;
export const MOVE_SPEED = 0.15;
export const RUN_SPEED_BASE = 0.3;
export const RUN_SPEED_MAX = 0.9;
export const ACCELERATION = 0.0002;

// Visuals
export const SKY_COLOR_HEX = '#87CEEB';
export const FOG_DISTANCE = 25;

// Helper to mix colors for Fog
export const hexToRgb = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : { r: 0, g: 0, b: 0 };
}

export const COLORS: Record<BlockType, { top: string; side: string; front: string; detail?: string }> = {
  [BlockType.GRASS]: { 
    top: '#7CBD38',  // Vivid Grass Green
    side: '#8B5E3C', // Dirt Brown
    front: '#8B5E3C',
    detail: '#7CBD38' // Grass overhang color
  },
  [BlockType.DIRT]: { 
    top: '#8B5E3C', 
    side: '#8B5E3C', 
    front: '#8B5E3C' 
  },
  [BlockType.STONE]: { 
    top: '#7D7D7D', 
    side: '#7D7D7D', 
    front: '#7D7D7D',
    detail: '#666666'
  },
  [BlockType.WOOD]: { 
    top: '#A07851', 
    side: '#A07851', 
    front: '#A07851' 
  },
  [BlockType.LEAVES]: { 
    top: '#3ea329', 
    side: '#3ea329', 
    front: '#3ea329' 
  },
  [BlockType.GOLD]: { 
    top: '#FCEE4B', // Gold block yellow
    side: '#FCEE4B', 
    front: '#FCEE4B',
    detail: '#E6C62C' // Darker gold for bevel
  },
  [BlockType.TNT]: { 
    top: '#DB3625', // TNT Red
    side: '#DB3625', 
    front: '#DB3625',
    detail: '#FFFFFF' // The white band
  },
  [BlockType.LAVA]: { 
    top: '#CF1020', 
    side: '#CF1020', 
