import { BlockType, Entity, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  RUN_SPEED_BASE, 
  RUN_SPEED_MAX, 
  SPEED_INCREMENT,
  LEVEL_DISTANCE,
  ACCELERATION, 
  LANE_WIDTH 
} from '../constants';

export class GameEngine {
  public entities: Entity[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false
  };

  private lastGenZ = 10;
  private currentSpeed = RUN_SPEED_BASE;
  private score = 0;
  private lives = 3;
  private level = 1;

  constructor() {
    this.reset();
  }

  reset() {
    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false
    };
    this.entities = [];
    this.currentSpeed = RUN_SPEED_BASE;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;

    // Initial ground generation
    for (let z = 0; z < 20; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean }, deltaTime: number) {
    // 1. Calculate Level & Speed
    // Level up every LEVEL_DISTANCE units
    this.level = Math.floor(Math.max(0, this.player.position.z) / LEVEL_DISTANCE) + 1;

    const targetSpeed = Math.min(
      RUN_SPEED_BASE + (this.level - 1) * SPEED_INCREMENT, 
      RUN_SPEED_MAX
    );

    // Smooth acceleration towards target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += ACCELERATION;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Movement (Strafe)
    // Smoothly interpolate towards target lane or just move raw
    const moveSpeed = 0.15;
    if (input.left) this.player.position.x -= moveSpeed;
    if (input.right) this.player.position.x += moveSpeed;

    // Clamp X
    if (this.player.position.x < -LANE_WIDTH * 1.5) this.player.position.x = -LANE_WIDTH * 1.5;
    if (this.player.position.x > LANE_WIDTH * 1.5) this.player.position.x = LANE_WIDTH * 1.5;

    // 4. Jump & Gravity
    if (input.jump && !this.player.isJumping) {
      this.player.velocity.y = JUMP_FORCE;
      this.player.isJumping = true;
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision (Simple floor at y=0)
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
    }

    // 5. World Generation
    // Generate ahead
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();
  }

  private generateSlice(z: number) {
    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS, // Pattern
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    // Random Obstacles & Collectibles (only after z > 10)
    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; // -1, 0, 1
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty scaler: slightly more obstacles as level increases
      const obstacleChance = Math.min(0.15 + (this.level * 0.01), 0.3);

      if (rand < obstacleChance) {
        // Obstacle: TNT or Stone
        const type = Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE;
        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Sometimes stack them
        if (Math.random() > 0.7) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.6 && rand < 0.8) {
        // Collectible: Gold
        // Often in a row
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z }, // Float slightly
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      // Simple AABB
      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
    } else if (entity.type === BlockType.TNT || entity.type === BlockType.STONE || entity.type === BlockType.LAVA) {
      // Hit obstacle
      this.lives -= 1;
      entity.collected = true; // remove entity to prevent multi-hit
    }
  }

  public getState() {
    return {
      entities: this.entities,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0,
      gameOver: this.lives <= 0
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  // Linear Interpolation
  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  // Mix color with Fog
  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    // Fog factor: 0 = clear, 1 = full fog
    // Start fog at 5 units away, full at FOG_DISTANCE
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));

    // Non-linear fog for better look
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  // Project 3D point to 2D
  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number) => {
    const rx = p.x - camX;
    const ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Functions ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, // Corners: TL, TR, BR, BL
    dist: number
  ) => {
    const baseColor = COLORS[type];

    // 1. Draw Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);
    drawQuad(ctx, p1, p2, p3, p4, color);

    // 2. Draw Details based on Type

    // GRASS Side: Draw Green Top 1/4
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);

        // Interpolate points to find the bottom of the grass layer (25% down)
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; // Left down
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; // Right down

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT Side: Draw White Band and "TNT"
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);

        // Middle 1/3 is white
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        // Draw "TNT" roughly using black rectangles if close enough
        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             // Center of the white band
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;

             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }

    // TNT Top: Fuse square
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33;
        const t2 = 0.66;

        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };

        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };

        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // Gold: Bevel Effect
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); // Thicker line when close
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // Stone: Noise
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));

        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;

           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);

           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);

           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    // Stroke edges
    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, 
    width: number, height: number
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height),
        ftr: project(v.ftr, camX, camY, camZ, width, height),
        fb: project(v.fb, camX, camY, camZ, width, height),
        fbr: project(v.fbr, camX, camY, camZ, width, height),
        bt: project(v.bt, camX, camY, camZ, width, height),
        btr: project(v.btr, camX, camY, camZ, width, height),
        bb: project(v.bb, camX, camY, camZ, width, height),
        bbr: project(v.bbr, camX, camY, camZ, width, height),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    // Draw Front
    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist);
    }

    // Draw Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist);
    }

    // Draw Top
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist);
    }

  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score}`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }
    if (state.lives <= 0) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Draw Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    skyGrad.addColorStop(0, '#4ea7d6');
    skyGrad.addColorStop(1, '#87CEEB');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    const camX = state.player.position.x;
    const camY = state.player.position.y + 1.6 + bob;
    const camZ = state.player.position.z - 0.5;

    // Render
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, width, height);
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { GameEngine } from './services/engine';
import { COLORS, BlockType } from './constants';

enum AppState {
  MENU,
  HELP,
  PLAYING,
  GAME_OVER
}

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.MENU);
  const [finalScore, setFinalScore] = useState(0);
  const engineRef = useRef<GameEngine>(new GameEngine());

  // We store input in a Ref so the game loop reads it without triggering React renders
  const inputState = useRef({
    left: false,
    right: false,
    jump: false
  });

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (appState !== AppState.PLAYING) return;

      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = true;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = true;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = true;
          break;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = false;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = false;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = false;
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [appState]);

  const startGame = () => {
    engineRef.current.reset();
    inputState.current = { left: false, right: false, jump: false };
    setAppState(AppState.PLAYING);
  };

  const handleGameOver = (score: number) => {
    setFinalScore(score);
    setAppState(AppState.GAME_OVER);
  };

  // Helper to render a block preview
  const BlockPreview = ({ type, label, desc }: { type: BlockType, label: string, desc: string }) => {
     const color = COLORS[type];
     return (
       <div className="flex items-center gap-4 mb-4">
          <div className="w-12 h-12 relative transform rotate-6 hover:rotate-12 transition-transform shadow-lg border-2 border-black/20" 
               style={{ backgroundColor: color.front, boxShadow: `4px 4px 0px ${color.side}` }}>
               <div className="absolute top-0 w-full h-1/3" style={{ backgroundColor: color.top }}></div>
               {type === BlockType.TNT && <div className="absolute top-1/3 w-full h-1/3 bg-white/90 text-[8px] flex items-center justify-center font-bold text-black">TNT</div>}
               {type === BlockType.GOLD && <div className="absolute inset-0 flex items-center justify-center"><div className="w-2 h-2 bg-white/50 rounded-full"></div></div>}
          </div>
          <div className="text-left">
            <div className="font-bold text-lg text-white">{label}</div>
            <div className="text-sm text-gray-300">{desc}</div>
          </div>
       </div>
     )
  };

  return (
    <div className="w-full h-screen bg-neutral-900 flex flex-col items-center justify-center relative overflow-hidden">

      {/* Menu Screen */}
      {appState === AppState.MENU && (
        <div className="z-10 text-center p-10 bg-black/60 backdrop-blur-sm border-4 border-green-600 rounded-lg shadow-[0_0_20px_rgba(0,255,0,0.5)] max-w-lg w-full">
          <h1 className="text-6xl mb-4 text-green-400 font-bold tracking-tighter drop-shadow-md">BLOCKY RUNNER</h1>
          <p className="text-xl text-gray-300 mb-8 font-mono">Run fast. Collect Gold. Survive.</p>
          <div className="flex flex-col gap-4">
            <button 
              onClick={startGame}
              className="px-8 py-4 bg-green-600 hover:bg-green-500 text-white text-2xl font-bold border-b-4 border-green-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              START RUN
            </button>
            <button 
              onClick={() => setAppState(AppState.HELP)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white text-xl font-bold border-b-4 border-blue-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              HOW TO PLAY
            </button>
          </div>
        </div>
      )}

      {/* Help Screen */}
      {appState === AppState.HELP && (
        <div className="z-10 p-8 bg-black/80 backdrop-blur-md border-4 border-blue-500 rounded-lg shadow-[0_0_20px_rgba(59,130,246,0.5)] max-w-2xl w-full text-white">
          <h2 className="text-4xl text-blue-400 mb-6 font-bold text-center border-b-2 border-blue-500/30 pb-4">HOW TO PLAY</h2>

          <div className="grid grid-cols-2 gap-8">
            <div>
              <h3 className="text-xl text-yellow-400 mb-4 font-bold uppercase tracking-wider">Controls</h3>
              <div className="space-y-4 font-mono text-lg">
                <div className="flex items-center gap-3">
