import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean }, deltaTime: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;
        // Boost speed slightly on level up
        this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); // Allow exceeding base max slightly
    }

    // Smooth acceleration to target speed if not there
    const targetSpeed = Math.min(
      settings.startSpeed + (this.level - 1) * 0.04, 
      settings.maxSpeed
    );

    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity
    if (input.jump && !this.player.isJumping) {
      this.player.velocity.y = JUMP_FORCE;
      this.player.isJumping = true;
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
    } else {
      // Obstacle Hit
      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          let color = '#7D7D7D';
          if (entity.type === BlockType.TNT) color = '#DB3625';
          if (entity.type === BlockType.CREEPER) color = '#0DA70D';
          if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

          this.spawnParticles(entity.position, color, 20);
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4, 
                  y: (Math.random()) * 0.4, 
                  z: (Math.random() - 0.5) * 0.4 
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0,
      gameOver: this.lives <= 0,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);
    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        // Map 2D face features to the quad p1..p4 (TL, TR, BR, BL)
        // Eyes
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        // Helper to map UV to XY
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        // Draw Eyes
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); // Left Eye
        drawRect(e2x, e2y, eyeW, eyeH); // Right Eye
        drawRect(0.35, 0.45, 0.3, 0.25); // Nose
        drawRect(0.25, 0.6, 0.1, 0.2); // Mouth L
        drawRect(0.65, 0.6, 0.1, 0.2); // Mouth R
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist);
    }
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist);
    }
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score}`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `TARGET: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }
    if (state.lives <= 0) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    skyGrad.addColorStop(0, '#4ea7d6');
    skyGrad.addColorStop(1, '#87CEEB');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera State
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    const camX = state.player.position.x;
    const camY = state.player.position.y + 1.6 + bob;
    const camZ = state.player.position.z - 0.5;
    const tilt = state.player.tilt;

    // Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, tilt, width, height);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">TARGET: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { GameEngine } from './services/engine';
import { COLORS } from './constants';
import { BlockType, Difficulty, HighScore } from './types';

enum AppState {
  MENU,
  HELP,
  PLAYING,
  GAME_OVER
}

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.MENU);
  const [finalScore, setFinalScore] = useState(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
  const [playerName, setPlayerName] = useState('Player');
  const [highScores, setHighScores] = useState<HighScore[]>([]);
  const engineRef = useRef<GameEngine>(new GameEngine());

  const inputState = useRef({
    left: false,
    right: false,
    jump: false
  });

  // Load High Scores
  useEffect(() => {
    const stored = localStorage.getItem('blockyRunnerHighScores');
    if (stored) {
      setHighScores(JSON.parse(stored));
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (appState !== AppState.PLAYING) return;

      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = true;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = true;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = true;
          break;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = false;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = false;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = false;
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [appState]);

  const startGame = () => {
    if (!playerName.trim()) {
        alert("Please enter your name!");
        return;
    }
    engineRef.current.reset(selectedDifficulty);
    inputState.current = { left: false, right: false, jump: false };
    setAppState(AppState.PLAYING);
  };

  const handleGameOver = (score: number) => {
    setFinalScore(score);

    // Save High Score
    const newScore: HighScore = {
      name: playerName,
      score: score,
      difficulty: selectedDifficulty,
      date: new Date().toLocaleDateString()
    };

    const newScores = [...highScores, newScore].sort((a, b) => b.score - a.score).slice(0, 5); // Keep top 5
    setHighScores(newScores);
    localStorage.setItem('blockyRunnerHighScores', JSON.stringify(newScores));

    setAppState(AppState.GAME_OVER);
  };

  const BlockPreview = ({ type, label, desc }: { type: BlockType, label: string, desc: string }) => {
     const color = COLORS[type];
     return (
       <div className="flex items-center gap-4 mb-4">
          <div className="w-12 h-12 relative transform rotate-6 hover:rotate-12 transition-transform shadow-lg border-2 border-black/20" 
               style={{ backgroundColor: color.front, boxShadow: `4px 4px 0px ${color.side}` }}>
               <div className="absolute top-0 w-full h-1/3" style={{ backgroundColor: color.top }}></div>
               {type === BlockType.TNT && <div className="absolute top-1/3 w-full h-1/3 bg-white/90 text-[8px] flex items-center justify-center font-bold text-black">TNT</div>}
               {type === BlockType.CREEPER && <div className="absolute inset-0 flex items-center justify-center text-black font-bold text-xs">:(</div>}
               {type === BlockType.GOLD && <div className="absolute inset-0 flex items-center justify-center"><div className="w-2 h-2 bg-white/50 rounded-full"></div></div>}
          </div>
          <div className="text-left">
            <div className="font-bold text-lg text-white">{label}</div>
            <div className="text-sm text-gray-300">{desc}</div>
          </div>
       </div>
     )
  };

  return (
    <div className="w-full h-screen bg-neutral-900 flex flex-col items-center justify-center relative overflow-hidden">

      {/* Menu Screen */}
      {appState === AppState.MENU && (
        <div className="z-10 text-center p-10 bg-black/60 backdrop-blur-sm border-4 border-green-600 rounded-lg shadow-[0_0_20px_rgba(0,255,0,0.5)] max-w-lg w-full max-h-screen overflow-y-auto">
          <h1 className="text-6xl mb-2 text-green-400 font-bold tracking-tighter drop-shadow-md">BLOCKY RUNNER</h1>
          <p className="text-xl text-gray-300 mb-6 font-mono">Run fast. Collect Gold. Survive.</p>

          <div className="mb-6 flex flex-col items-center">
             <label className="text-sm text-green-300 mb-1 font-bold">PLAYER NAME</label>
             <input 
                type="text" 
                value={playerName} 
                onChange={(e) => setPlayerName(e.target.value)}
                maxLength={10}
                className="bg-black/50 border-2 border-green-600 text-white text-center text-xl p-2 rounded w-48 focus:outline-none focus:border-green-400 font-mono uppercase"
             />
          </div>

          <div className="mb-8">
            <div className="text-white text-lg mb-2 font-bold">SELECT DIFFICULTY</div>
            <div className="flex gap-2 justify-center">
              {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map((diff) => (
                <button
                  key={diff}
                  onClick={() => setSelectedDifficulty(diff)}
                  className={`px-4 py-2 border-b-4 font-bold transition-all text-sm ${
                    selectedDifficulty === diff 
                      ? 'bg-yellow-500 text-black border-yellow-700 -translate-y-1' 
                      : 'bg-gray-700 text-gray-300 border-gray-900 hover:bg-gray-600'
                  }`}
                >
                  {diff}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <button 
              onClick={startGame}
              className="px-8 py-4 bg-green-600 hover:bg-green-500 text-white text-2xl font-bold border-b-4 border-green-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              START RUN
            </button>
            <button 
              onClick={() => setAppState(AppState.HELP)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white text-xl font-bold border-b-4 border-blue-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              HOW TO PLAY
            </button>
          </div>

          {highScores.length > 0 && (
             <div className="mt-8 bg-black/40 p-4 rounded border border-white/10">
                <h3 className="text-yellow-400 font-bold mb-2 border-b border-white/20 pb-1">TOP SCORES</h3>
                <div className="text-sm font-mono space-y-1">
                   {highScores.map((score, idx) => (
                       <div key={idx} className="flex justify-between text-gray-300">
                          <span>{idx+1}. {score.name}</span>
                          <span className="text-white">{score.score}</span>
                       </div>
                   ))}
                </div>
             </div>
          )}
        </div>
      )}

      {/* Help Screen */}
      {appState === AppState.HELP && (
        <div className="z-10 p-8 bg-black/80 backdrop-blur-md border-4 border-blue-500 rounded-lg shadow-[0_0_20px_rgba(59,130,246,0.5)] max-w-2xl w-full text-white">
          <h2 className="text-4xl text-blue-400 mb-6 font-bold text-center border-b-2 border-blue-500/30 pb-4">HOW TO PLAY</h2>

          <div className="grid grid-cols-2 gap-8">
            <div>
              <h3 className="text-xl text-yellow-400 mb-4 font-bold uppercase tracking-wider">Controls</h3>
              <div className="space-y-4 font-mono text-lg">
                <div className="flex items-center gap-3">
                  <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">A</span> / <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">←</span> 
                  <span>Move Left</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">D</span> / <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">→</span> 
                  <span>Move Right</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="bg-gray-700 p-2 px-4 rounded border-b-4 border-gray-900">SPACE</span> 
                  <span>Jump</span>
                </div>
              </div>
            </div>

            <div>
              <h3 className="text-xl text-yellow-400 mb-4 font-bold uppercase tracking-wider">Blocks</h3>
              <BlockPreview type={BlockType.GOLD} label="Gold Block" desc="Collect to LEVEL UP!" />
              <BlockPreview type={BlockType.CREEPER} label="Creeper" desc="Avoid! Appears Lvl 2+" />
              <BlockPreview type={BlockType.SKELETON} label="Skeleton" desc="Avoid! Appears Lvl 3+" />
            </div>
          </div>

          <button 
            onClick={() => setAppState(AppState.MENU)}
            className="mt-8 w-full py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded border-b-4 border-gray-900 active:border-b-0 active:translate-y-1 transition-all"
          >
            BACK TO MENU
          </button>
        </div>
      )}

      {/* Game Canvas */}
      {appState === AppState.PLAYING && (
        <GameCanvas 
          engine={engineRef.current} 
          onGameOver={handleGameOver} 
          inputState={inputState}
        />
      )}

      {/* Game Over Screen */}
      {appState === AppState.GAME_OVER && (
        <div className="z-10 text-center p-8 bg-red-900/80 backdrop-blur-sm border-4 border-red-600 rounded-lg shadow-[0_0_30px_rgba(255,0,0,0.5)] min-w-[300px]">
          <h2 className="text-5xl text-red-200 mb-2 font-bold">GAME OVER</h2>
          <div className="text-xl text-white mb-6">Good run, {playerName}!</div>
          <div className="text-4xl text-yellow-400 mb-8 font-mono border-2 border-yellow-600 p-4 bg-black/30 rounded inline-block">Score: {finalScore}</div>

          <div className="flex gap-4 justify-center">
            <button 
              onClick={startGame}
              className="px-8 py-4 bg-gray-100 hover:bg-white text-black text-xl font-bold border-b-4 border-gray-400 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              TRY AGAIN
            </button>
            <button 
              onClick={() => setAppState(AppState.MENU)}
              className="px-8 py-4 bg-black/50 hover:bg-black/40 text-white text-xl font-bold border-b-4 border-black/70 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              MENU
            </button>
          </div>
        </div>
      )}

      {/* Background decoration for menu */}
      {appState !== AppState.PLAYING && (
         <div className="absolute inset-0 -z-10 overflow-hidden opacity-30">
            <div className="absolute w-full h-full bg-[linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111),linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111)] bg-[length:40px_40px] bg-[position:0_0,20px_20px] bg-neutral-800" />
         </div>
      )}
    </div>
  );
}

