import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean }, deltaTime: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity
    if (input.jump && !this.player.isJumping) {
      this.player.velocity.y = JUMP_FORCE;
      this.player.isJumping = true;
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
    } else {
      // Obstacle Hit
      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          let color = '#7D7D7D';
          if (entity.type === BlockType.TNT) color = '#DB3625';
          if (entity.type === BlockType.CREEPER) color = '#0DA70D';
          if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

          this.spawnParticles(entity.position, color, 20);
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4, 
                  y: (Math.random()) * 0.4, 
                  z: (Math.random() - 0.5) * 0.4 
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0,
      gameOver: this.lives <= 0,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget
    };
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { GameEngine } from './services/engine';
import { COLORS } from './constants';
import { BlockType, Difficulty, HighScore } from './types';

enum AppState {
  MENU,
  HELP,
  PLAYING,
  GAME_OVER
}

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.MENU);
  const [finalScore, setFinalScore] = useState(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
  const [playerName, setPlayerName] = useState('Player');
  const [highScores, setHighScores] = useState<HighScore[]>([]);
  const engineRef = useRef<GameEngine>(new GameEngine());

  const inputState = useRef({
    left: false,
    right: false,
    jump: false
  });

  // Load High Scores
  useEffect(() => {
    const stored = localStorage.getItem('blockyRunnerHighScores');
    if (stored) {
      setHighScores(JSON.parse(stored));
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (appState !== AppState.PLAYING) return;

      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = true;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = true;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = true;
          break;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      switch(e.code) {
        case 'ArrowLeft':
        case 'KeyA':
          inputState.current.left = false;
          break;
        case 'ArrowRight':
        case 'KeyD':
          inputState.current.right = false;
          break;
        case 'Space':
        case 'ArrowUp':
        case 'KeyW':
          inputState.current.jump = false;
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [appState]);

  const startGame = () => {
    if (!playerName.trim()) {
        alert("Please enter your name!");
        return;
    }
    engineRef.current.reset(selectedDifficulty);
    inputState.current = { left: false, right: false, jump: false };
    setAppState(AppState.PLAYING);
  };

  const handleGameOver = (score: number) => {
    setFinalScore(score);

    // Save High Score
    const newScore: HighScore = {
      name: playerName,
      score: score,
      difficulty: selectedDifficulty,
      date: new Date().toLocaleDateString()
    };

    const newScores = [...highScores, newScore].sort((a, b) => b.score - a.score).slice(0, 5); // Keep top 5
    setHighScores(newScores);
    localStorage.setItem('blockyRunnerHighScores', JSON.stringify(newScores));

    setAppState(AppState.GAME_OVER);
  };

  const BlockPreview = ({ type, label, desc }: { type: BlockType, label: string, desc: string }) => {
     const color = COLORS[type];
     return (
       <div className="flex items-center gap-4 mb-4">
          <div className="w-12 h-12 relative transform rotate-6 hover:rotate-12 transition-transform shadow-lg border-2 border-black/20 shrink-0" 
               style={{ backgroundColor: color.front, boxShadow: `4px 4px 0px ${color.side}` }}>
               <div className="absolute top-0 w-full h-1/3" style={{ backgroundColor: color.top }}></div>
               {type === BlockType.TNT && <div className="absolute top-1/3 w-full h-1/3 bg-white/90 text-[8px] flex items-center justify-center font-bold text-black">TNT</div>}
               {type === BlockType.CREEPER && <div className="absolute inset-0 flex items-center justify-center text-black font-bold text-xs">:(</div>}
               {type === BlockType.GOLD && <div className="absolute inset-0 flex items-center justify-center"><div className="w-2 h-2 bg-white/50 rounded-full"></div></div>}
          </div>
          <div className="text-left">
            <div className="font-bold text-lg text-white">{label}</div>
            <div className="text-sm text-gray-300 leading-tight">{desc}</div>
          </div>
       </div>
     )
  };

  return (
    <div className="w-full h-screen bg-neutral-900 flex flex-col items-center justify-center relative overflow-hidden">

      {/* Menu Screen */}
      {appState === AppState.MENU && (
        <div className="z-10 text-center p-10 bg-black/60 backdrop-blur-sm border-4 border-green-600 rounded-lg shadow-[0_0_20px_rgba(0,255,0,0.5)] max-w-lg w-full max-h-screen overflow-y-auto">
          <h1 className="text-6xl mb-2 text-green-400 font-bold tracking-tighter drop-shadow-md">BLOCKY RUNNER</h1>
          <p className="text-xl text-gray-300 mb-6 font-mono">Run fast. Collect Gold. Survive.</p>

          <div className="mb-6 flex flex-col items-center">
             <label className="text-sm text-green-300 mb-1 font-bold">PLAYER NAME</label>
             <input 
                type="text" 
                value={playerName} 
                onChange={(e) => setPlayerName(e.target.value)}
                maxLength={10}
