import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';
import { audioService } from './audio';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0,
    jumpCount: 0,
    phaseActive: false,
    phaseTimeRemaining: 0,
    phaseCooldown: 0,
    doubleJumpCooldown: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;
  private gameWon = false;
  private shakeIntensity = 0;
  private lastJumpInput = false;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0,
      jumpCount: 0,
      phaseActive: false,
      phaseTimeRemaining: 0,
      phaseCooldown: 0,
      doubleJumpCooldown: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;
    this.gameWon = false;
    this.shakeIntensity = 0;
    this.lastJumpInput = false;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean; phase?: boolean }, deltaTime: number) {
    if (this.gameWon) return;

    // Decay Shake
    if (this.shakeIntensity > 0.001) {
        this.shakeIntensity *= 0.85; // Decay factor
    } else {
        this.shakeIntensity = 0;
    }

    // Update Abilities
    if (this.player.phaseTimeRemaining > 0) {
        this.player.phaseTimeRemaining -= deltaTime;
        if (this.player.phaseTimeRemaining <= 0) this.player.phaseActive = false;
    }
    if (this.player.phaseCooldown > 0) this.player.phaseCooldown -= deltaTime;
    if (this.player.doubleJumpCooldown > 0) this.player.doubleJumpCooldown -= deltaTime;

    // Activate Phase
    if (input.phase && this.player.phaseCooldown <= 0) {
        this.player.phaseActive = true;
        this.player.phaseTimeRemaining = 5000; // 5 seconds
        this.player.phaseCooldown = 20000; // 20 seconds cooldown
        // Visual cue for activation
        this.spawnParticles(this.player.position, '#00FFFF', 20, 1.5);
    }

    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity (Double Jump Logic)
    const jumpPressed = input.jump && !this.lastJumpInput;
    this.lastJumpInput = input.jump;

    if (jumpPressed) {
        if (!this.player.isJumping) {
            // First Jump
            this.player.velocity.y = JUMP_FORCE;
            this.player.isJumping = true;
            this.player.jumpCount = 1;
            audioService.playJump();
        } else if (this.player.jumpCount < 2 && this.player.doubleJumpCooldown <= 0) {
            // Double Jump (Only if cooldown is 0)
            this.player.velocity.y = JUMP_FORCE * 0.9;
            this.player.jumpCount = 2;
            this.player.doubleJumpCooldown = 20000; // 20 seconds cooldown
            audioService.playJump();
            // Visual feedback: puff
            this.spawnParticles(this.player.position, '#FFFFFF', 8, 0.5);
        }
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
      this.player.jumpCount = 0; // Reset jumps
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
      audioService.playCollect();

      // WIN CONDITION
      if (this.score >= 250) {
        this.gameWon = true;
      }

    } else {
      // Obstacle Hit
      if (this.player.phaseActive) return; // IGNORE OBSTACLE COLLISIONS IF PHASED

      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          if (entity.type === BlockType.TNT) {
              // TNT EXPLOSION
              this.shakeIntensity = 0.5; // High shake amplitude

              // Multiple colored bursts for explosion
              this.spawnParticles(entity.position, '#DB3625', 20, 2.0); // Red core
              this.spawnParticles(entity.position, '#FF8C00', 20, 1.8); // Orange mid
              this.spawnParticles(entity.position, '#FFFF00', 15, 1.5); // Yellow outer
              this.spawnParticles(entity.position, '#FFFFFF', 10, 2.5); // White sparks
          } else {
              // Standard obstacle particles
              let color = '#7D7D7D';
              if (entity.type === BlockType.CREEPER) color = '#0DA70D';
              if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

              this.spawnParticles(entity.position, color, 20);
          }

          audioService.playHit();
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number, speedMult: number = 1.0) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4 * speedMult, 
                  y: (Math.random()) * 0.4 * speedMult, 
                  z: (Math.random() - 0.5) * 0.4 * speedMult
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0 && !this.gameWon,
      gameOver: this.lives <= 0,
      gameWon: this.gameWon,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget,
      shakeIntensity: this.shakeIntensity
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        // Map 2D face features to the quad p1..p4 (TL, TR, BR, BL)
        // Eyes
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        // Helper to map UV to XY
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        // Draw Eyes
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); // Left Eye
        drawRect(e2x, e2y, eyeW, eyeH); // Right Eye
        drawRect(0.35, 0.45, 0.3, 0.25); // Nose
        drawRect(0.25, 0.6, 0.1, 0.2); // Mouth L
        drawRect(0.65, 0.6, 0.1, 0.2); // Mouth R
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    // HUD - Abilities
    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const jumpCD = Math.ceil(state.player.doubleJumpCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);

        let html = '';

        // Double Jump
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${jumpCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50'} flex items-center justify-center text-xs font-bold relative">
                       DJ
                       ${jumpCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${jumpCD}</div>` : ''}
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">JUMP</span>
                 </div>`;

        // Phase
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">
                       PH
                       ${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}
                       ${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">"B"</span>
                 </div>`;

        abilitiesRef.current.innerHTML = html;
    }


    // Game Over / Win Condition
    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         // Tint sky cyan when phased
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }

    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera State
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    let camX = state.player.position.x;
    let camY = state.player.position.y + 1.6 + bob;
    let camZ = state.player.position.z - 0.5;
    const tilt = state.player.tilt;

    // Apply Screen Shake
    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.6)' : 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}>
         {/* HUD Injected by JS */}
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

export enum BlockType {
  GRASS = 'GRASS',
  DIRT = 'DIRT',
  STONE = 'STONE',
  WOOD = 'WOOD',
  LEAVES = 'LEAVES',
  GOLD = 'GOLD', // Collectible
  TNT = 'TNT',   // Obstacle
  LAVA = 'LAVA',
  CREEPER = 'CREEPER',   // Mob Obstacle
  SKELETON = 'SKELETON'  // Mob Obstacle
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Entity {
  id: string;
  type: BlockType;
  position: Point3D;
  size: number;
  collected?: boolean;
  rotation?: number; // For gold blocks
}

export interface Particle {
  id: string;
  position: Point3D;
  velocity: Point3D;
  life: number; // 0 to 1
  color: string;
  size: number;
}

export interface GameState {
  isPlaying: boolean;
  score: number;
  distance: number;
  speed: number;
  lives: number;
  gameOver: boolean;
  gameWon: boolean;
  level: number;
  particles: Particle[];
  goldCollected: number;
  levelTarget: number;
  shakeIntensity: number;
}

export interface PlayerState {
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
  tilt: number; // Camera tilt
  jumpCount: number;
  // Abilities
  phaseActive: boolean;
  phaseTimeRemaining: number;
  phaseCooldown: number;
}

export interface HighScore {
  name: string;
  score: number;
  difficulty: Difficulty;
  date: string;
}

import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';
import { audioService } from './audio';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0,
    jumpCount: 0,
    phaseActive: false,
    phaseTimeRemaining: 0,
    phaseCooldown: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;
  private gameWon = false;
  private shakeIntensity = 0;
  private lastJumpInput = false;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0,
      jumpCount: 0,
      phaseActive: false,
      phaseTimeRemaining: 0,
      phaseCooldown: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;
    this.gameWon = false;
    this.shakeIntensity = 0;
    this.lastJumpInput = false;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean; phase?: boolean }, deltaTime: number) {
    if (this.gameWon) return;

    // Decay Shake
    if (this.shakeIntensity > 0.001) {
        this.shakeIntensity *= 0.85; // Decay factor
    } else {
        this.shakeIntensity = 0;
    }

    // Update Abilities
    if (this.player.phaseTimeRemaining > 0) {
        this.player.phaseTimeRemaining -= deltaTime;
        if (this.player.phaseTimeRemaining <= 0) this.player.phaseActive = false;
    }
    if (this.player.phaseCooldown > 0) this.player.phaseCooldown -= deltaTime;

    // Activate Phase
    if (input.phase && this.player.phaseCooldown <= 0) {
        this.player.phaseActive = true;
        this.player.phaseTimeRemaining = 5000; // 5 seconds
        this.player.phaseCooldown = 20000; // 20 seconds cooldown
        // Visual cue for activation
        this.spawnParticles(this.player.position, '#00FFFF', 20, 1.5);
    }

    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity (Double Jump Logic)
    const jumpPressed = input.jump && !this.lastJumpInput;
    this.lastJumpInput = input.jump;

    if (jumpPressed) {
        if (!this.player.isJumping) {
            // First Jump
            this.player.velocity.y = JUMP_FORCE;
            this.player.isJumping = true;
            this.player.jumpCount = 1;
            audioService.playJump();
        } else if (this.player.jumpCount < 2) {
            // Double Jump (Always available if count < 2)
            this.player.velocity.y = JUMP_FORCE * 0.9;
            this.player.jumpCount = 2;
            audioService.playJump();
            // Visual feedback: puff
            this.spawnParticles(this.player.position, '#FFFFFF', 8, 0.5);
        }
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
      this.player.jumpCount = 0; // Reset jumps
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
      audioService.playCollect();

      // WIN CONDITION
      if (this.score >= 250) {
        this.gameWon = true;
      }

    } else {
      // Obstacle Hit
      if (this.player.phaseActive) return; // IGNORE OBSTACLE COLLISIONS IF PHASED

      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          if (entity.type === BlockType.TNT) {
              // TNT EXPLOSION
              this.shakeIntensity = 0.5; // High shake amplitude

              // Multiple colored bursts for explosion
              this.spawnParticles(entity.position, '#DB3625', 20, 2.0); // Red core
              this.spawnParticles(entity.position, '#FF8C00', 20, 1.8); // Orange mid
              this.spawnParticles(entity.position, '#FFFF00', 15, 1.5); // Yellow outer
              this.spawnParticles(entity.position, '#FFFFFF', 10, 2.5); // White sparks
          } else {
              // Standard obstacle particles
              let color = '#7D7D7D';
              if (entity.type === BlockType.CREEPER) color = '#0DA70D';
              if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

              this.spawnParticles(entity.position, color, 20);
          }

          audioService.playHit();
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number, speedMult: number = 1.0) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4 * speedMult, 
                  y: (Math.random()) * 0.4 * speedMult, 
                  z: (Math.random() - 0.5) * 0.4 * speedMult
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0 && !this.gameWon,
      gameOver: this.lives <= 0,
      gameWon: this.gameWon,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget,
      shakeIntensity: this.shakeIntensity
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        // Map 2D face features to the quad p1..p4 (TL, TR, BR, BL)
        // Eyes
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        // Helper to map UV to XY
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        // Draw Eyes
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); // Left Eye
        drawRect(e2x, e2y, eyeW, eyeH); // Right Eye
        drawRect(0.35, 0.45, 0.3, 0.25); // Nose
        drawRect(0.25, 0.6, 0.1, 0.2); // Mouth L
        drawRect(0.65, 0.6, 0.1, 0.2); // Mouth R
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    // HUD - Abilities
    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);

        // Check if jump is available (less than 2 used)
        const jumpAvailable = state.player.jumpCount < 2;

        let html = '';

        // Double Jump
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">
                       DJ
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">JUMP</span>
                 </div>`;

        // Phase
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">
                       PH
                       ${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}
                       ${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">"B"</span>
                 </div>`;

        abilitiesRef.current.innerHTML = html;
    }


    // Game Over / Win Condition
    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         // Tint sky cyan when phased
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }

    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera State
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    let camX = state.player.position.x;
    let camY = state.player.position.y + 1.6 + bob;
    let camZ = state.player.position.z - 0.5;
    const tilt = state.player.tilt;

    // Apply Screen Shake
    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.6)' : 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}>
         {/* HUD Injected by JS */}
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

export enum BlockType {
  GRASS = 'GRASS',
  DIRT = 'DIRT',
  STONE = 'STONE',
  WOOD = 'WOOD',
  LEAVES = 'LEAVES',
  GOLD = 'GOLD', // Collectible
  TNT = 'TNT',   // Obstacle
  LAVA = 'LAVA',
  CREEPER = 'CREEPER',   // Mob Obstacle
  SKELETON = 'SKELETON'  // Mob Obstacle
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Entity {
  id: string;
  type: BlockType;
  position: Point3D;
  size: number;
  collected?: boolean;
  rotation?: number; // For gold blocks
}

export interface Particle {
  id: string;
  position: Point3D;
  velocity: Point3D;
  life: number; // 0 to 1
  color: string;
  size: number;
}

export interface GameState {
  isPlaying: boolean;
  score: number;
  distance: number;
  speed: number;
  lives: number;
  gameOver: boolean;
  gameWon: boolean;
  level: number;
  particles: Particle[];
  goldCollected: number;
  levelTarget: number;
  shakeIntensity: number;
}

export interface PlayerState {
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
  tilt: number; // Camera tilt
  jumpCount: number;
  // Abilities
  phaseActive: boolean;
  phaseTimeRemaining: number;
}

export interface HighScore {
  name: string;
  score: number;
  difficulty: Difficulty;
  date: string;
}

import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';
import { audioService } from './audio';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0,
    jumpCount: 0,
    phaseActive: false,
    phaseTimeRemaining: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;
  private gameWon = false;
  private shakeIntensity = 0;
  private lastJumpInput = false;
  private lastPhaseInput = false;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0,
      jumpCount: 0,
      phaseActive: false,
      phaseTimeRemaining: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;
    this.gameWon = false;
    this.shakeIntensity = 0;
    this.lastJumpInput = false;
    this.lastPhaseInput = false;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean; phase?: boolean }, deltaTime: number) {
    if (this.gameWon) return;

    // Decay Shake
    if (this.shakeIntensity > 0.001) {
        this.shakeIntensity *= 0.85; // Decay factor
    } else {
        this.shakeIntensity = 0;
    }

    // Update Abilities
    if (this.player.phaseTimeRemaining > 0) {
        this.player.phaseTimeRemaining -= deltaTime;
        if (this.player.phaseTimeRemaining <= 0) this.player.phaseActive = false;
    }

    // Activate Phase
    const phasePressed = input.phase && !this.lastPhaseInput;
    this.lastPhaseInput = !!input.phase;

    if (phasePressed) {
        this.player.phaseActive = true;
        this.player.phaseTimeRemaining = 5000; // 5 seconds duration
        // Visual cue for activation
        this.spawnParticles(this.player.position, '#00FFFF', 20, 1.5);
    }

    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity (Double Jump Logic)
    const jumpPressed = input.jump && !this.lastJumpInput;
    this.lastJumpInput = input.jump;

    if (jumpPressed) {
        if (!this.player.isJumping) {
            // First Jump
            this.player.velocity.y = JUMP_FORCE;
            this.player.isJumping = true;
            this.player.jumpCount = 1;
            audioService.playJump();
        } else if (this.player.jumpCount < 2) {
            // Double Jump (Always available if count < 2)
            this.player.velocity.y = JUMP_FORCE * 0.9;
            this.player.jumpCount = 2;
            audioService.playJump();
            // Visual feedback: puff
            this.spawnParticles(this.player.position, '#FFFFFF', 8, 0.5);
        }
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
      this.player.jumpCount = 0; // Reset jumps
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
      audioService.playCollect();

      // WIN CONDITION
      if (this.score >= 250) {
        this.gameWon = true;
      }

    } else {
      // Obstacle Hit
      if (this.player.phaseActive) return; // IGNORE OBSTACLE COLLISIONS IF PHASED

      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          if (entity.type === BlockType.TNT) {
              // TNT EXPLOSION
              this.shakeIntensity = 0.5; // High shake amplitude

              // Multiple colored bursts for explosion
              this.spawnParticles(entity.position, '#DB3625', 20, 2.0); // Red core
              this.spawnParticles(entity.position, '#FF8C00', 20, 1.8); // Orange mid
              this.spawnParticles(entity.position, '#FFFF00', 15, 1.5); // Yellow outer
              this.spawnParticles(entity.position, '#FFFFFF', 10, 2.5); // White sparks
          } else {
              // Standard obstacle particles
              let color = '#7D7D7D';
              if (entity.type === BlockType.CREEPER) color = '#0DA70D';
              if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

              this.spawnParticles(entity.position, color, 20);
          }

          audioService.playHit();
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number, speedMult: number = 1.0) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4 * speedMult, 
                  y: (Math.random()) * 0.4 * speedMult, 
                  z: (Math.random() - 0.5) * 0.4 * speedMult
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0 && !this.gameWon,
      gameOver: this.lives <= 0,
      gameWon: this.gameWon,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget,
      shakeIntensity: this.shakeIntensity
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        // Map 2D face features to the quad p1..p4 (TL, TR, BR, BL)
        // Eyes
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        // Helper to map UV to XY
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        // Draw Eyes
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); // Left Eye
        drawRect(e2x, e2y, eyeW, eyeH); // Right Eye
        drawRect(0.35, 0.45, 0.3, 0.25); // Nose
        drawRect(0.25, 0.6, 0.1, 0.2); // Mouth L
        drawRect(0.65, 0.6, 0.1, 0.2); // Mouth R
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    // HUD - Abilities
    if (abilitiesRef.current) {
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);

        // Check if jump is available (less than 2 used)
        const jumpAvailable = state.player.jumpCount < 2;

        let html = '';

        // Double Jump
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">
                       DJ
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">JUMP</span>
                 </div>`;

        // Phase
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : 'border-green-400 bg-green-900/50'} flex items-center justify-center text-xs font-bold relative">
                       PH
                       ${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">"B"</span>
                 </div>`;

        abilitiesRef.current.innerHTML = html;
    }


    // Game Over / Win Condition
    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         // Tint sky cyan when phased
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }

    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera State
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    let camX = state.player.position.x;
    let camY = state.player.position.y + 1.6 + bob;
    let camZ = state.player.position.z - 0.5;
    const tilt = state.player.tilt;

    // Apply Screen Shake
    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.6)' : 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}>
         {/* HUD Injected by JS */}
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

export enum BlockType {
  GRASS = 'GRASS',
  DIRT = 'DIRT',
  STONE = 'STONE',
  WOOD = 'WOOD',
  LEAVES = 'LEAVES',
  GOLD = 'GOLD', // Collectible
  TNT = 'TNT',   // Obstacle
  LAVA = 'LAVA',
  CREEPER = 'CREEPER',   // Mob Obstacle
  SKELETON = 'SKELETON'  // Mob Obstacle
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Entity {
  id: string;
  type: BlockType;
  position: Point3D;
  size: number;
  collected?: boolean;
  rotation?: number; // For gold blocks
}

export interface Particle {
  id: string;
  position: Point3D;
  velocity: Point3D;
  life: number; // 0 to 1
  color: string;
  size: number;
}

export interface GameState {
  isPlaying: boolean;
  score: number;
  distance: number;
  speed: number;
  lives: number;
  gameOver: boolean;
  gameWon: boolean;
  level: number;
  particles: Particle[];
  goldCollected: number;
  levelTarget: number;
  shakeIntensity: number;
}

export interface PlayerState {
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
  tilt: number; // Camera tilt
  jumpCount: number;
  // Abilities
  phaseActive: boolean;
  phaseTimeRemaining: number;
  phaseCooldown: number;
}

export interface HighScore {
  name: string;
  score: number;
  difficulty: Difficulty;
  date: string;
}

import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';
import { audioService } from './audio';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0,
    jumpCount: 0,
    phaseActive: false,
    phaseTimeRemaining: 0,
    phaseCooldown: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;
  private gameWon = false;
  private shakeIntensity = 0;
  private lastJumpInput = false;
  private lastPhaseInput = false;

  constructor() {
    this.reset(Difficulty.MEDIUM);
  }

  reset(difficulty: Difficulty) {
    this.difficulty = difficulty;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0,
      jumpCount: 0,
      phaseActive: false,
      phaseTimeRemaining: 0,
      phaseCooldown: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;
    this.gameWon = false;
    this.shakeIntensity = 0;
    this.lastJumpInput = false;
    this.lastPhaseInput = false;

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean; phase?: boolean }, deltaTime: number) {
    if (this.gameWon) return;

    // Decay Shake
    if (this.shakeIntensity > 0.001) {
        this.shakeIntensity *= 0.85; // Decay factor
    } else {
        this.shakeIntensity = 0;
    }

    // Update Abilities
    if (this.player.phaseTimeRemaining > 0) {
        this.player.phaseTimeRemaining -= deltaTime;
        if (this.player.phaseTimeRemaining <= 0) this.player.phaseActive = false;
    }
    if (this.player.phaseCooldown > 0) {
        this.player.phaseCooldown -= deltaTime;
    }

    // Activate Phase
    const phasePressed = input.phase && !this.lastPhaseInput;
    this.lastPhaseInput = !!input.phase;

    if (phasePressed && this.player.phaseCooldown <= 0) {
        this.player.phaseActive = true;
        this.player.phaseTimeRemaining = 5000; // 5 seconds duration
        this.player.phaseCooldown = 10000; // 5s duration + 5s cooldown
        // Visual cue for activation
        this.spawnParticles(this.player.position, '#00FFFF', 20, 1.5);
    }

    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity (Double Jump Logic)
    const jumpPressed = input.jump && !this.lastJumpInput;
    this.lastJumpInput = input.jump;

    if (jumpPressed) {
        if (!this.player.isJumping) {
            // First Jump
            this.player.velocity.y = JUMP_FORCE;
            this.player.isJumping = true;
            this.player.jumpCount = 1;
            audioService.playJump();
        } else if (this.player.jumpCount < 2) {
            // Double Jump (Always available if count < 2)
            this.player.velocity.y = JUMP_FORCE * 0.9;
            this.player.jumpCount = 2;
            audioService.playJump();
            // Visual feedback: puff
            this.spawnParticles(this.player.position, '#FFFFFF', 8, 0.5);
        }
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
      this.player.jumpCount = 0; // Reset jumps
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
      audioService.playCollect();

      // WIN CONDITION
      if (this.score >= 250) {
        this.gameWon = true;
      }

    } else {
      // Obstacle Hit
      if (this.player.phaseActive) return; // IGNORE OBSTACLE COLLISIONS IF PHASED

      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          if (entity.type === BlockType.TNT) {
              // TNT EXPLOSION
              this.shakeIntensity = 0.5; // High shake amplitude

              // Multiple colored bursts for explosion
              this.spawnParticles(entity.position, '#DB3625', 20, 2.0); // Red core
              this.spawnParticles(entity.position, '#FF8C00', 20, 1.8); // Orange mid
              this.spawnParticles(entity.position, '#FFFF00', 15, 1.5); // Yellow outer
              this.spawnParticles(entity.position, '#FFFFFF', 10, 2.5); // White sparks
          } else {
              // Standard obstacle particles
              let color = '#7D7D7D';
              if (entity.type === BlockType.CREEPER) color = '#0DA70D';
              if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

              this.spawnParticles(entity.position, color, 20);
          }

          audioService.playHit();
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number, speedMult: number = 1.0) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4 * speedMult, 
                  y: (Math.random()) * 0.4 * speedMult, 
                  z: (Math.random() - 0.5) * 0.4 * speedMult
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0 && !this.gameWon,
      gameOver: this.lives <= 0,
      gameWon: this.gameWon,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget,
      shakeIntensity: this.shakeIntensity
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        // Map 2D face features to the quad p1..p4 (TL, TR, BR, BL)
        // Eyes
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        // Helper to map UV to XY
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        // Draw Eyes
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); // Left Eye
        drawRect(e2x, e2y, eyeW, eyeH); // Right Eye
        drawRect(0.35, 0.45, 0.3, 0.25); // Nose
        drawRect(0.25, 0.6, 0.1, 0.2); // Mouth L
        drawRect(0.65, 0.6, 0.1, 0.2); // Mouth R
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    // HUD - Abilities
    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);

        // Check if jump is available (less than 2 used)
        const jumpAvailable = state.player.jumpCount < 2;

        let html = '';

        // Double Jump
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">
                       DJ
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">JUMP</span>
                 </div>`;

        // Phase
        html += `<div class="flex flex-col items-center">
                   <div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">
                       PH
                       ${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}
                       ${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}
                   </div>
                   <span class="text-[10px] mt-1 text-gray-400">"B"</span>
                 </div>`;

        abilitiesRef.current.innerHTML = html;
    }


    // Game Over / Win Condition
    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         // Tint sky cyan when phased
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }

    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera State
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    let camX = state.player.position.x;
    let camY = state.player.position.y + 1.6 + bob;
    let camZ = state.player.position.z - 0.5;
    const tilt = state.player.tilt;

    // Apply Screen Shake
    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    for (const entity of sortedEntities) {
      drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 80 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    // Crosshair
    ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.6)' : 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width/2 - 8, height/2);
    ctx.lineTo(width/2 + 8, height/2);
    ctx.moveTo(width/2, height/2 - 8);
    ctx.lineTo(width/2, height/2 + 8);
    ctx.stroke();

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}>
         {/* HUD Injected by JS */}
      </div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll) - not used much here but good for completeness
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      // Draw Faces (Painter's algorithm per part isn't perfect but sufficient for convex separate parts)
      // We rely on face normal culling implicitly by checking projection order or just drawing typical visible faces?
      // Since we are behind, we see Back, Top/Bottom, Left/Right.
      // We rarely see front.

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space (assuming CCW winding)

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));
      };

      // Indices for CCW winding
      // Front: 0,1,2,3
      // Back: 5,4,7,6
      // Top: 4,5,1,0
      // Bottom: 3,2,6,7
      // Left: 4,0,3,7
      // Right: 1,5,6,2

      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation state
      const runAnim = isJumping ? 0.5 : Math.sin(time * 0.015) * 1.2;

      const skinColor = '#F3C09A';
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#303090'; // Indigo
      const shoesColor = '#111111';

      // -- LEGS --
      // Dimensions: 0.25 x 0.75 x 0.25 approx
      // Position relative to player center (x, 0, z)
      // Player pos is ground level? No, player pos usually centroid or feet. Engine says feet y=0.

      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = pos.y + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: pos.y + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: shoesColor, left: pantsColor, right: pantsColor },
          { x: -runAnim * 0.5, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: pos.y + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: shoesColor, left: pantsColor, right: pantsColor },
          { x: runAnim * 0.5, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: '#3B2618', top: '#3B2618', bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 }, // Maybe look up/down?
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: runAnim * 0.5, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: -runAnim * 0.5, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    // Draw faces back to front? 
    // Simplified logic: If Z of face center is > Z of entity center...
    // But since we are looking down +Z mainly, we see Front, Top, and Side.
    // Wait, TPV camera is at Z - 4. Entity is at Z. We see Back face?
    // Camera is at PlayerZ - 4. World is +Z. 
    // So we look at the Back of the entity if it is ahead of us.
    // The existing drawCube was optimized for FPV looking forward (seeing Back? No, seeing Front/Side/Top of block in front).

    // Correction:
    // If Entity Z > Camera Z (Entity is in front), we see its "Back" face (the face with lower Z)?
    // Standard coordinates:
    // +Z is into screen.
    // Front face: Z - hs (Towards viewer if viewer is at -Z).
    // Back face: Z + hs (Away from viewer).
    // So if Camera is at Z-4, looking at Z, we see the face at Z-hs.
    // The existing logic:
    // `v.ft` is `z - hs`. This is the face CLOSEST to camera (if camera is -Z).
    // So yes, `FRONT` is correct label for face at `z-hs`.

    // Logic:
    // `z - hs > camZ + 0.1` -> The front face is in front of camera. Draw it.
    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
    // We usually don't see bottom
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // TPV Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Camera trails behind player
    let camX = state.player.position.x * 0.8; // Lag slightly on X for effect
    let camY = state.player.position.y + 2.8 + bob; // Look from above
    let camZ = state.player.position.z - 4.5; // Behind
    const tilt = state.player.tilt;

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        // If we reach entities closer than player, draw player first
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Fallback if player is closer than all entities
    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines (Only if fast)
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll) - not used much here but good for completeness
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      // Draw Faces (Painter's algorithm per part isn't perfect but sufficient for convex separate parts)
      // We rely on face normal culling implicitly by checking projection order or just drawing typical visible faces?
      // Since we are behind, we see Back, Top/Bottom, Left/Right.
      // We rarely see front.

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space (assuming CCW winding)

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));
      };

      // Indices for CCW winding
      // Front: 0,1,2,3
      // Back: 5,4,7,6
      // Top: 4,5,1,0
      // Bottom: 3,2,6,7
      // Left: 4,0,3,7
      // Right: 1,5,6,2

      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      const runFreq = 0.025; // Speed of animation
      const runAmp = 1.0; // Amplitude of limb swing (~57 degrees)

      // Calculate Phase
      // Use time directly.
      const animPhase = time * runFreq;

      // Swing Logic
      // Sin wave for rotation
      const rawSwing = Math.sin(animPhase);

      // If jumping, limbs freeze in a "mid-air" pose or slight movement
      const swing = isJumping ? 0.3 : rawSwing * runAmp;

      // Bobbing (Bounce up and down while running)
      // Happens twice per cycle (every step)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;

      // Adjusted Position
      const steveY = pos.y + bob;

      // Colors
      const skinColor = '#F3C09A';
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#303090'; // Indigo
      const shoesColor = '#111111';

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      // Limb Rotations
      // Left Leg: Forward/Back. Let's say positive is forward kick.
      // Right Leg: Opposite.
      // Left Arm: Opposite to Left Leg.
      // Right Arm: Opposite to Right Leg.

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; // Opposite to Left Leg
      const rightArmRot = -swing; // Opposite to Right Leg

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: shoesColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: shoesColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: '#3B2618', top: '#3B2618', bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          camX, camY, camZ, tilt, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    // Draw faces back to front? 
    // Simplified logic: If Z of face center is > Z of entity center...
    // But since we are looking down +Z mainly, we see Front, Top, and Side.
    // Wait, TPV camera is at Z - 4. Entity is at Z. We see Back face?
    // Camera is at PlayerZ - 4. World is +Z. 
    // So we look at the Back of the entity if it is ahead of us.
    // The existing drawCube was optimized for FPV looking forward (seeing Back? No, seeing Front/Side/Top of block in front).

    // Correction:
    // If Entity Z > Camera Z (Entity is in front), we see its "Back" face (the face with lower Z)?
    // Standard coordinates:
    // +Z is into screen.
    // Front face: Z - hs (Towards viewer if viewer is at -Z).
    // Back face: Z + hs (Away from viewer).
    // So if Camera is at Z-4, looking at Z, we see the face at Z-hs.
    // The existing logic:
    // `v.ft` is `z - hs`. This is the face CLOSEST to camera (if camera is -Z).
    // So yes, `FRONT` is correct label for face at `z-hs`.

    // Logic:
    // `z - hs > camZ + 0.1` -> The front face is in front of camera. Draw it.
    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
    // We usually don't see bottom
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // TPV Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Camera trails behind player
    let camX = state.player.position.x * 0.8; // Lag slightly on X for effect
    let camY = state.player.position.y + 2.8 + bob; // Look from above
    let camZ = state.player.position.z - 4.5; // Behind
    const tilt = state.player.tilt;

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        // If we reach entities closer than player, draw player first
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    // Fallback if player is closer than all entities
    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines (Only if fast)
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      const runFreq = 0.025; 
      const runAmp = 1.0; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);
      const swing = isJumping ? 0.3 : rawSwing * runAmp;
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // TPV Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 2.8 + bob; 
    let camZ = state.player.position.z - 4.5; 
    const tilt = state.player.tilt;

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      // Slowed down frequency significantly for a smoother, weightier run
      const runFreq = 0.010; 
      // Reduced amplitude slightly for less jerkiness
      const runAmp = 0.9; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);
      const swing = isJumping ? 0.3 : rawSwing * runAmp;
      // Smoother bobbing
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.08;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // TPV Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 2.8 + bob; 
    let camZ = state.player.position.z - 4.5; 
    const tilt = state.player.tilt;

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    const rz = p.z - camZ;

    if (rz <= 0.1) return null;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      // Slowed down frequency significantly for a smoother, weightier run
      const runFreq = 0.010; 
      // Reduced amplitude slightly for less jerkiness
      const runAmp = 0.9; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);

      // Minecraft-style: Continue running animation in mid-air (Sprint Jumping)
      const swing = rawSwing * runAmp; 

      // Smoother bobbing (Only on ground)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.08;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // TPV Camera
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 2.8 + bob; 
    let camZ = state.player.position.z - 4.5; 
    const tilt = state.player.tilt;

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number, pitch: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    let rz = p.z - camZ;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Rotate (Pitch - X axis)
    if (pitch !== 0) {
        const cos = Math.cos(pitch);
        const sin = Math.sin(pitch);
        const ny = ry * cos + rz * sin;
        const nz = -ry * sin + rz * cos;
        ry = ny;
        rz = nz;
    }

    if (rz <= 0.1) return null;

    // 4. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt, pitch));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      // Slowed down frequency significantly for a smoother, weightier run
      const runFreq = 0.010; 
      // Reduced amplitude slightly for less jerkiness
      const runAmp = 0.9; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);

      // Minecraft-style: Continue running animation in mid-air (Sprint Jumping)
      const swing = rawSwing * runAmp; 

      // Smoother bobbing (Only on ground)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.08;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number, pitch: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt, pitch);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt, pitch),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt, pitch),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt, pitch),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt, pitch),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt, pitch),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt, pitch),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt, pitch),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt, pitch),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera Configuration (High-Angle / Top-Down view)
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Increased Y height and angled pitch down for "from above" view
    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 7.5 + bob; 
    let camZ = state.player.position.z - 5.5; 
    const tilt = state.player.tilt;
    const pitch = 0.6; // ~35 degrees looking down

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt, pitch);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number, pitch: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    let rz = p.z - camZ;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Rotate (Pitch - X axis)
    if (pitch !== 0) {
        const cos = Math.cos(pitch);
        const sin = Math.sin(pitch);
        const ny = ry * cos + rz * sin;
        const nz = -ry * sin + rz * cos;
        ry = ny;
        rz = nz;
    }

    if (rz <= 0.1) return null;

    // 4. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt, pitch));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      // Fast, energetic frequency (Minecraft sprint)
      const runFreq = 0.025; 
      // Large amplitude for full stride
      const runAmp = 1.2; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);

      // Minecraft-style: Continue running animation in mid-air (Sprint Jumping)
      const swing = rawSwing * runAmp; 

      // Smoother bobbing (Only on ground)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number, pitch: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt, pitch);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt, pitch),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt, pitch),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt, pitch),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt, pitch),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt, pitch),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt, pitch),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt, pitch),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt, pitch),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera Configuration (High-Angle / Top-Down view)
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Increased Y height and angled pitch down for "from above" view
    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 7.5 + bob; 
    let camZ = state.player.position.z - 5.5; 
    const tilt = state.player.tilt;
    const pitch = 0.6; // ~35 degrees looking down

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt, pitch);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number, pitch: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    let rz = p.z - camZ;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Rotate (Pitch - X axis)
    if (pitch !== 0) {
        const cos = Math.cos(pitch);
        const sin = Math.sin(pitch);
        const ny = ry * cos + rz * sin;
        const nz = -ry * sin + rz * cos;
        ry = ny;
        rz = nz;
    }

    if (rz <= 0.1) return null;

    // 4. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt, pitch));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, '#009999');
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean
  ) => {
      // Animation Config
      // Slowed down frequency by 30% from 0.025 to 0.0175
      const runFreq = 0.0175; 
      // Large amplitude for full stride
      const runAmp = 1.2; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);

      // Minecraft-style: Continue running animation in mid-air (Sprint Jumping)
      const swing = rawSwing * runAmp; 

      // Smoother bobbing (Only on ground)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;

      const steveY = pos.y + bob;

      // Updated Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = '#00AAAA'; // Cyan
      const pantsColor = '#3B3696'; // Indigo Blue
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number, pitch: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt, pitch);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt, pitch),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt, pitch),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt, pitch),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt, pitch),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt, pitch),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt, pitch),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt, pitch),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt, pitch),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera Configuration (High-Angle / Top-Down view)
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Increased Y height and angled pitch down for "from above" view
    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 7.5 + bob; 
    let camZ = state.player.position.z - 5.5; 
    const tilt = state.player.tilt;
    const pitch = 0.6; // ~35 degrees looking down

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    let steveDrawn = false;

    // Draw Loop
    for (const entity of sortedEntities) {
        if (!steveDrawn && entity.position.z < state.player.position.z) {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
            steveDrawn = true;
        }
        drawCube(ctx, entity, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive);
    }

    if (!steveDrawn) {
         drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt, pitch);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}>❤️❤️❤️</div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
      <div className="absolute top-4 right-4 text-white/70 text-sm font-mono select-none bg-black/30 p-2 rounded">
        WASD to Move • SPACE to Jump • B to Phase
      </div>
    </div>
  );
};

export enum BlockType {
  GRASS = 'GRASS',
  DIRT = 'DIRT',
  STONE = 'STONE',
  WOOD = 'WOOD',
  LEAVES = 'LEAVES',
  GOLD = 'GOLD', // Collectible
  TNT = 'TNT',   // Obstacle
  LAVA = 'LAVA',
  CREEPER = 'CREEPER',   // Mob Obstacle
  SKELETON = 'SKELETON'  // Mob Obstacle
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface Entity {
  id: string;
  type: BlockType;
  position: Point3D;
  size: number;
  collected?: boolean;
  rotation?: number; // For gold blocks
}

export interface Particle {
  id: string;
  position: Point3D;
  velocity: Point3D;
  life: number; // 0 to 1
  color: string;
  size: number;
}

export interface RemotePlayer {
  id: string;
  name: string;
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
  jumpCount: number;
  colors: { shirt: string; pants: string };
  speed: number;
}

export interface GameState {
  isPlaying: boolean;
  score: number;
  distance: number;
  speed: number;
  lives: number;
  gameOver: boolean;
  gameWon: boolean;
  level: number;
  particles: Particle[];
  goldCollected: number;
  levelTarget: number;
  shakeIntensity: number;
  isMultiplayer: boolean;
  otherPlayers: RemotePlayer[];
}

export interface PlayerState {
  position: Point3D;
  velocity: Point3D;
  isJumping: boolean;
  tilt: number; // Camera tilt
  jumpCount: number;
  // Abilities
  phaseActive: boolean;
  phaseTimeRemaining: number;
  phaseCooldown: number;
}

export interface HighScore {
  name: string;
  score: number;
  difficulty: Difficulty;
  date: string;
}

import { BlockType, Difficulty, Entity, Particle, PlayerState, Point3D, RemotePlayer } from '../types';
import { 
  GRAVITY, 
  JUMP_FORCE, 
  DIFFICULTY_SETTINGS,
  LANE_WIDTH,
  MOVE_ACCEL_X,
  FRICTION_X,
  MAX_SPEED_X,
  CAMERA_TILT_FACTOR,
  BASE_LEVEL_TARGET,
  LEVEL_TARGET_INCREMENT
} from '../constants';
import { audioService } from './audio';

export class GameEngine {
  public entities: Entity[] = [];
  public particles: Particle[] = [];
  public player: PlayerState = {
    position: { x: 0, y: 0, z: 0 },
    velocity: { x: 0, y: 0, z: 0 },
    isJumping: false,
    tilt: 0,
    jumpCount: 0,
    phaseActive: false,
    phaseTimeRemaining: 0,
    phaseCooldown: 0
  };

  private lastGenZ = 10;
  private currentSpeed = 0;
  private score = 0;
  private lives = 3;
  private level = 1;
  private difficulty: Difficulty = Difficulty.MEDIUM;
  private particleIdCounter = 0;
  private goldCollectedInLevel = 0;
  private levelTarget = BASE_LEVEL_TARGET;
  private gameWon = false;
  private shakeIntensity = 0;
  private lastJumpInput = false;
  private lastPhaseInput = false;

  // Multiplayer
  private isMultiplayer = false;
  private bots: RemotePlayer[] = [];

  constructor() {
    this.reset(Difficulty.MEDIUM, false);
  }

  reset(difficulty: Difficulty, isMultiplayer: boolean = false) {
    this.difficulty = difficulty;
    this.isMultiplayer = isMultiplayer;
    const settings = DIFFICULTY_SETTINGS[difficulty];

    this.player = {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      isJumping: false,
      tilt: 0,
      jumpCount: 0,
      phaseActive: false,
      phaseTimeRemaining: 0,
      phaseCooldown: 0
    };
    this.entities = [];
    this.particles = [];
    this.currentSpeed = settings.startSpeed;
    this.lastGenZ = 5;
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.goldCollectedInLevel = 0;
    this.levelTarget = BASE_LEVEL_TARGET;
    this.gameWon = false;
    this.shakeIntensity = 0;
    this.lastJumpInput = false;
    this.lastPhaseInput = false;

    // Initialize Bots for Multiplayer
    this.bots = [];
    if (this.isMultiplayer) {
        const colors = [
            { shirt: '#FF0000', pants: '#0000FF' }, // Red/Blue
            { shirt: '#00FF00', pants: '#800080' }, // Green/Purple
            { shirt: '#FFFF00', pants: '#000000' }, // Yellow/Black
            { shirt: '#FFA500', pants: '#555555' }, // Orange/Gray
        ];
        for(let i=0; i<4; i++) {
            this.bots.push({
                id: `bot_${i}`,
                name: `Player ${i+2}`,
                position: { x: (Math.random() * 2 - 1) * LANE_WIDTH, y: 0, z: 0 },
                velocity: { x: 0, y: 0, z: 0 },
                isJumping: false,
                jumpCount: 0,
                colors: colors[i],
                speed: settings.startSpeed
            });
        }
    }

    // Initial ground generation
    for (let z = 0; z < 25; z++) {
      this.generateSlice(z);
    }
  }

  update(input: { left: boolean; right: boolean; jump: boolean; phase?: boolean }, deltaTime: number) {
    if (this.gameWon) return;

    // Decay Shake
    if (this.shakeIntensity > 0.001) {
        this.shakeIntensity *= 0.85; // Decay factor
    } else {
        this.shakeIntensity = 0;
    }

    // Update Abilities
    if (this.player.phaseTimeRemaining > 0) {
        this.player.phaseTimeRemaining -= deltaTime;
        if (this.player.phaseTimeRemaining <= 0) this.player.phaseActive = false;
    }
    if (this.player.phaseCooldown > 0) {
        this.player.phaseCooldown -= deltaTime;
    }

    // Activate Phase
    const phasePressed = input.phase && !this.lastPhaseInput;
    this.lastPhaseInput = !!input.phase;

    if (phasePressed && this.player.phaseCooldown <= 0) {
        this.player.phaseActive = true;
        this.player.phaseTimeRemaining = 5000; // 5 seconds duration
        this.player.phaseCooldown = 10000; // 5s duration + 5s cooldown
        // Visual cue for activation
        this.spawnParticles(this.player.position, '#00FFFF', 20, 1.5);
    }

    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // 1. Leveling Logic (Gold Based)
    if (this.goldCollectedInLevel >= this.levelTarget) {
        this.level++;
        this.goldCollectedInLevel = 0;
        this.levelTarget += LEVEL_TARGET_INCREMENT;

        // Boost speed slightly on level up ONLY if not Easy
        if (this.difficulty !== Difficulty.EASY) {
             this.currentSpeed = Math.min(this.currentSpeed + 0.05, settings.maxSpeed + 0.2); 
        }
    }

    // Calculate target speed
    let targetSpeed = settings.startSpeed;

    if (this.difficulty !== Difficulty.EASY) {
        // Increase speed with level for Medium/Hard
        targetSpeed = Math.min(
          settings.startSpeed + (this.level - 1) * 0.04, 
          settings.maxSpeed
        );
    }

    // Smooth acceleration to target speed
    if (this.currentSpeed < targetSpeed) {
      this.currentSpeed += settings.accel;
    }

    // 2. Move Player Forward
    this.player.position.z += this.currentSpeed;

    // 3. Lateral Physics (Inertia-based)
    if (input.left) {
        this.player.velocity.x -= MOVE_ACCEL_X;
    }
    if (input.right) {
        this.player.velocity.x += MOVE_ACCEL_X;
    }

    // Apply Friction
    this.player.velocity.x *= FRICTION_X;

    // Clamp Velocity
    if (this.player.velocity.x > MAX_SPEED_X) this.player.velocity.x = MAX_SPEED_X;
    if (this.player.velocity.x < -MAX_SPEED_X) this.player.velocity.x = -MAX_SPEED_X;

    // Apply Position
    this.player.position.x += this.player.velocity.x;

    // Tilt Effect
    this.player.tilt = -this.player.velocity.x * CAMERA_TILT_FACTOR;

    // Clamp X Position (Walls)
    const MAX_X = LANE_WIDTH * 1.8;
    if (this.player.position.x < -MAX_X) {
        this.player.position.x = -MAX_X;
        this.player.velocity.x = 0;
    }
    if (this.player.position.x > MAX_X) {
        this.player.position.x = MAX_X;
        this.player.velocity.x = 0;
    }

    // 4. Jump & Gravity (Double Jump Logic)
    const jumpPressed = input.jump && !this.lastJumpInput;
    this.lastJumpInput = input.jump;

    if (jumpPressed) {
        if (!this.player.isJumping) {
            // First Jump
            this.player.velocity.y = JUMP_FORCE;
            this.player.isJumping = true;
            this.player.jumpCount = 1;
            audioService.playJump();
        } else if (this.player.jumpCount < 2) {
            // Double Jump (Always available if count < 2)
            this.player.velocity.y = JUMP_FORCE * 0.9;
            this.player.jumpCount = 2;
            audioService.playJump();
            // Visual feedback: puff
            this.spawnParticles(this.player.position, '#FFFFFF', 8, 0.5);
        }
    }

    this.player.velocity.y -= GRAVITY;
    this.player.position.y += this.player.velocity.y;

    // Ground Collision
    if (this.player.position.y <= 0) {
      this.player.position.y = 0;
      this.player.velocity.y = 0;
      this.player.isJumping = false;
      this.player.jumpCount = 0; // Reset jumps
    }

    // 4.5 Update Bots
    if (this.isMultiplayer) {
        this.updateBots();
    }

    // 5. World Generation
    const renderDistance = 25;
    if (this.player.position.z + renderDistance > this.lastGenZ) {
      this.generateSlice(this.lastGenZ);
      this.lastGenZ++;
    }

    // Cleanup behind
    this.entities = this.entities.filter(e => e.position.z > this.player.position.z - 5);

    // 6. Collision Detection
    this.checkCollisions();

    // 7. Update Particles
    this.updateParticles();
  }

  private updateBots() {
      const settings = DIFFICULTY_SETTINGS[this.difficulty];

      this.bots.forEach(bot => {
          // AI: Rubber Banding Speed
          // If bot is behind player, speed up. If ahead, slow down.
          const distDiff = this.player.position.z - bot.position.z;
          let desiredSpeed = this.currentSpeed;

          if (distDiff > 10) desiredSpeed *= 1.1; // Catch up fast
          else if (distDiff > 0) desiredSpeed *= 1.02; // Catch up slow
          else if (distDiff < -10) desiredSpeed *= 0.9; // Wait up
          else desiredSpeed *= 0.98 + (Math.random() * 0.04); // Random fluctuation

          bot.speed += (desiredSpeed - bot.speed) * 0.1;
          bot.position.z += bot.speed;

          // AI: Obstacle Avoidance (Jump)
          // Look ahead in current X lane
          const lookAheadDist = 6;
          const imminentObstacle = this.entities.find(e => {
              if (e.collected || e.type === BlockType.GOLD) return false;
              const zDiff = e.position.z - bot.position.z;
              const xDiff = Math.abs(e.position.x - bot.position.x);
              return zDiff > 0 && zDiff < lookAheadDist && xDiff < 0.8;
          });

          if (imminentObstacle && !bot.isJumping) {
               // Jump random timing
               if (Math.random() > 0.1) {
                   bot.velocity.y = JUMP_FORCE;
                   bot.isJumping = true;
               }
          }

          // Physics
          bot.velocity.y -= GRAVITY;
          bot.position.y += bot.velocity.y;
          if (bot.position.y <= 0) {
              bot.position.y = 0;
              bot.velocity.y = 0;
              bot.isJumping = false;
          }
      });
  }

  private generateSlice(z: number) {
    const settings = DIFFICULTY_SETTINGS[this.difficulty];

    // Always ground
    for (let x = -2; x <= 2; x++) {
       this.entities.push({
         id: `ground_${z}_${x}`,
         type: (x + z) % 2 === 0 ? BlockType.GRASS : BlockType.GRASS,
         position: { x: x * LANE_WIDTH, y: -1, z },
         size: 1
       });
    }

    if (z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1; 
      const xPos = lane * LANE_WIDTH;
      const rand = Math.random();

      // Difficulty-based spawn rate
      const obstacleChance = Math.min(settings.obstacleChance + (this.level * 0.01), 0.4);

      if (rand < obstacleChance) {
        // Obstacle Selection based on Level
        let availableObstacles = [BlockType.STONE, BlockType.TNT];
        if (this.level >= 2) availableObstacles.push(BlockType.CREEPER);
        if (this.level >= 3) availableObstacles.push(BlockType.SKELETON);

        const type = availableObstacles[Math.floor(Math.random() * availableObstacles.length)];

        this.entities.push({
          id: `obs_${z}`,
          type,
          position: { x: xPos, y: 0, z },
          size: 1
        });

        // Stack logic (less likely for mobs)
        if (Math.random() > 0.7 && type !== BlockType.CREEPER && type !== BlockType.SKELETON) {
           this.entities.push({
            id: `obs_stack_${z}`,
            type: Math.random() > 0.5 ? BlockType.TNT : BlockType.STONE,
            position: { x: xPos, y: 1, z },
            size: 1
          });
        }
      } else if (rand > 0.5 && rand < 0.8) { 
        // Higher chance for gold to help players progress
        this.entities.push({
          id: `gold_${z}`,
          type: BlockType.GOLD,
          position: { x: xPos, y: 0.5 + (Math.sin(z) * 0.2), z },
          size: 0.5,
          rotation: 0
        });
      }
    }
  }

  private checkCollisions() {
    const playerBox = {
      x: this.player.position.x,
      y: this.player.position.y,
      z: this.player.position.z,
      w: 0.6,
      h: 0.9,
      d: 0.6
    };

    for (const entity of this.entities) {
      if (entity.collected) continue;

      const dx = Math.abs(playerBox.x - entity.position.x);
      const dy = Math.abs(playerBox.y - entity.position.y);
      const dz = Math.abs(playerBox.z - entity.position.z);

      const minDistX = (playerBox.w + entity.size) / 2;
      const minDistY = (playerBox.h + entity.size) / 2;
      const minDistZ = (playerBox.d + entity.size) / 2;

      if (dx < minDistX && dy < minDistY && dz < minDistZ) {
        this.handleCollision(entity);
      }
    }
  }

  private handleCollision(entity: Entity) {
    if (entity.type === BlockType.GOLD) {
      entity.collected = true;
      this.score += 10;
      this.goldCollectedInLevel++;
      this.spawnParticles(entity.position, '#FCEE4B', 10);
      audioService.playCollect();

      // WIN CONDITION
      if (this.score >= 250) {
        this.gameWon = true;
      }

    } else {
      // Obstacle Hit
      if (this.player.phaseActive) return; // IGNORE OBSTACLE COLLISIONS IF PHASED

      if (!entity.collected) { // Prevent double hits per frame
          this.lives -= 1;
          entity.collected = true;

          if (entity.type === BlockType.TNT) {
              // TNT EXPLOSION
              this.shakeIntensity = 0.5; // High shake amplitude

              // Multiple colored bursts for explosion
              this.spawnParticles(entity.position, '#DB3625', 20, 2.0); // Red core
              this.spawnParticles(entity.position, '#FF8C00', 20, 1.8); // Orange mid
              this.spawnParticles(entity.position, '#FFFF00', 15, 1.5); // Yellow outer
              this.spawnParticles(entity.position, '#FFFFFF', 10, 2.5); // White sparks
          } else {
              // Standard obstacle particles
              let color = '#7D7D7D';
              if (entity.type === BlockType.CREEPER) color = '#0DA70D';
              if (entity.type === BlockType.SKELETON) color = '#E3E3E3';

              this.spawnParticles(entity.position, color, 20);
          }

          audioService.playHit();
      }
    }
  }

  private spawnParticles(pos: Point3D, color: string, count: number, speedMult: number = 1.0) {
      for(let i=0; i<count; i++) {
          this.particles.push({
              id: `p_${this.particleIdCounter++}`,
              position: { x: pos.x, y: pos.y, z: pos.z },
              velocity: { 
                  x: (Math.random() - 0.5) * 0.4 * speedMult, 
                  y: (Math.random()) * 0.4 * speedMult, 
                  z: (Math.random() - 0.5) * 0.4 * speedMult
              },
              life: 1.0,
              color: color,
              size: Math.random() * 0.2 + 0.05
          });
      }
  }

  private updateParticles() {
      // Move particles
      for (const p of this.particles) {
          p.position.x += p.velocity.x;
          p.position.y += p.velocity.y;
          p.position.z += p.velocity.z;
          p.velocity.y -= 0.02; // Gravity for particles
          p.life -= 0.05;
      }
      // Remove dead particles
      this.particles = this.particles.filter(p => p.life > 0);
  }

  public getState() {
    return {
      entities: this.entities,
      particles: this.particles,
      player: this.player,
      score: this.score,
      lives: this.lives,
      speed: this.currentSpeed,
      level: this.level,
      distance: this.player.position.z,
      isPlaying: this.lives > 0 && !this.gameWon,
      gameOver: this.lives <= 0,
      gameWon: this.gameWon,
      goldCollected: this.goldCollectedInLevel,
      levelTarget: this.levelTarget,
      shakeIntensity: this.shakeIntensity,
      isMultiplayer: this.isMultiplayer,
      otherPlayers: this.bots
    };
  }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (score: number) => void;
  inputState: { current: { left: boolean; right: boolean; jump: boolean; phase?: boolean } };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number, pitch: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    let rz = p.z - camZ;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Rotate (Pitch - X axis)
    if (pitch !== 0) {
        const cos = Math.cos(pitch);
        const sin = Math.sin(pitch);
        const ny = ry * cos + rz * sin;
        const nz = -ry * sin + rz * cos;
        ry = ny;
        rz = nz;
    }

    if (rz <= 0.1) return null;

    // 4. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
    // ctx.stroke(); // Debug outline
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt, pitch));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling in 2D space

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, colors.front); // Use shirt color
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean,
      customColors: { shirt: string, pants: string } = { shirt: '#00AAAA', pants: '#3B3696' }
  ) => {
      // Animation Config
      const runFreq = 0.0175; 
      const runAmp = 1.2; 

      const animPhase = time * runFreq;
      const rawSwing = Math.sin(animPhase);

      // Minecraft-style: Continue running animation in mid-air (Sprint Jumping)
      const swing = rawSwing * runAmp; 

      // Smoother bobbing (Only on ground)
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;

      const steveY = pos.y + bob;

      // Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = customColors.shirt;
      const pantsColor = customColors.pants;
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; 
      const rightLegRot = swing;
      const leftArmRot = swing; 
      const rightArmRot = -swing; 

      // Left Leg
      drawStevePart(
          ctx, 
          { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Leg
      drawStevePart(
          ctx, 
          { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, 
          { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 },
          'LEG',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Torso
      drawStevePart(
          ctx, 
          { x: pos.x, y: hipY + torsoH/2, z: pos.z }, 
          { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 },
          'TORSO',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Head
      drawStevePart(
          ctx, 
          { x: pos.x, y: neckY + headS/2, z: pos.z }, 
          { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 },
          'HEAD',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Left Arm
      drawStevePart(
          ctx, 
          { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );

      // Right Arm
      drawStevePart(
          ctx, 
          { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, 
          { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 },
          'ARM',
          camX, camY, camZ, tilt, pitch, width, height, phaseActive
      );
  }

  // --- World Drawing ---

  const drawFaceDetails = (
    ctx: CanvasRenderingContext2D, 
    type: BlockType, 
    face: 'TOP' | 'SIDE' | 'FRONT', 
    p1: any, p2: any, p3: any, p4: any, 
    dist: number,
    phaseActive: boolean
  ) => {
    const baseColor = COLORS[type];

    // Base
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);

    if (phaseActive && type !== BlockType.GOLD) {
       ctx.globalAlpha = 0.5; // Ghostly
    }

    drawQuad(ctx, p1, p2, p3, p4, color);

    // Details 

    // GRASS
    if (type === BlockType.GRASS && face !== 'TOP') {
        const detailColor = applyFog(baseColor.detail!, dist);
        const grassH = 0.25;
        const p1_b = { x: lerp(p1.x, p4.x, grassH), y: lerp(p1.y, p4.y, grassH) }; 
        const p2_b = { x: lerp(p2.x, p3.x, grassH), y: lerp(p2.y, p3.y, grassH) }; 

        drawQuad(ctx, p1, p2, p2_b, p1_b, detailColor);
    }

    // TNT
    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33;
        const botH = 0.66;

        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };

        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);

        if (dist < 15) {
             ctx.fillStyle = applyFog('#000000', dist);
             const cx = (tl_w.x + tr_w.x + bl_w.x + br_w.x) / 4;
             const cy = (tl_w.y + tr_w.y + bl_w.y + br_w.y) / 4;
             const w = Math.abs(tr_w.x - tl_w.x) * 0.4;
             const h = Math.abs(bl_w.y - tl_w.y) * 0.6;
             ctx.fillRect(cx - w/2, cy - h/2, w, h);
        }
    }
    // TNT Top
    if (type === BlockType.TNT && face === 'TOP') {
        const detailColor = applyFog('#FFFFFF', dist);
        const t1 = 0.33; const t2 = 0.66;
        const te1 = { x: lerp(p1.x, p2.x, t1), y: lerp(p1.y, p2.y, t1) };
        const te2 = { x: lerp(p1.x, p2.x, t2), y: lerp(p1.y, p2.y, t2) };
        const be1 = { x: lerp(p4.x, p3.x, t1), y: lerp(p4.y, p3.y, t1) };
        const be2 = { x: lerp(p4.x, p3.x, t2), y: lerp(p4.y, p3.y, t2) };
        const c1 = { x: lerp(te1.x, be1.x, t1), y: lerp(te1.y, be1.y, t1) };
        const c2 = { x: lerp(te2.x, be2.x, t1), y: lerp(te2.y, be2.y, t1) };
        const c3 = { x: lerp(te2.x, be2.x, t2), y: lerp(te2.y, be2.y, t2) };
        const c4 = { x: lerp(te1.x, be1.x, t2), y: lerp(te1.y, be1.y, t2) };
        drawQuad(ctx, c1, c2, c3, c4, detailColor);
    }

    // CREEPER FACE
    if (type === BlockType.CREEPER && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#000000', dist);
        const eyeW = 0.2; const eyeH = 0.2;
        const e1x = 0.2; const e1y = 0.25;
        const e2x = 0.6; const e2y = 0.25;

        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }

        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(e1x, e1y, eyeW, eyeH); 
        drawRect(e2x, e2y, eyeW, eyeH); 
        drawRect(0.35, 0.45, 0.3, 0.25); 
        drawRect(0.25, 0.6, 0.1, 0.2); 
        drawRect(0.65, 0.6, 0.1, 0.2); 
    }

    // SKELETON FACE
    if (type === BlockType.SKELETON && face === 'FRONT' && dist < 20) {
        ctx.fillStyle = applyFog('#555555', dist);
        const mapUV = (u: number, v: number) => {
            const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
            const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
        }
        const drawRect = (u: number, v: number, w: number, h: number) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, ctx.fillStyle as string);
        }

        drawRect(0.2, 0.3, 0.2, 0.15); // Eye L
        drawRect(0.6, 0.3, 0.2, 0.15); // Eye R
        drawRect(0.45, 0.55, 0.1, 0.05); // Nose
        drawRect(0.2, 0.7, 0.6, 0.05); // Mouth Line
    }


    // GOLD
    if (type === BlockType.GOLD) {
        const detailColor = applyFog(baseColor.detail!, dist);
        ctx.strokeStyle = detailColor;
        ctx.lineWidth = Math.max(1, 40 / dist); 
        ctx.stroke(); 

        if (face === 'TOP' || face === 'FRONT') {
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            const cx = (p1.x + p2.x + p3.x + p4.x) / 4;
            const cy = (p1.y + p2.y + p3.y + p4.y) / 4;
            const s = 100 / dist;
            ctx.fillRect(cx, cy, s, s);
        }
    }

    // STONE NOISE
    if (type === BlockType.STONE && dist < 20) {
        ctx.fillStyle = applyFog(baseColor.detail!, dist);
        const seed = Math.floor(p1.x + p1.y); 
        const rnd = (i: number) => Math.abs(Math.sin(seed + i));
        for(let i=0; i<3; i++) {
           const u = 0.2 + rnd(i)*0.6;
           const v = 0.2 + rnd(i+10)*0.6;
           const topX = lerp(p1.x, p2.x, u); const topY = lerp(p1.y, p2.y, u);
           const botX = lerp(p4.x, p3.x, u); const botY = lerp(p4.y, p3.y, u);
           const px = lerp(topX, botX, v);
           const py = lerp(topY, botY, v);
           const size = Math.max(2, 20/dist);
           ctx.fillRect(px, py, size, size);
        }
    }

    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.globalAlpha = 1.0; // Reset Alpha
  };

  const drawCube = useCallback((
    ctx: CanvasRenderingContext2D, 
    entity: Entity, 
    camX: number, camY: number, camZ: number, tilt: number, pitch: number,
    width: number, height: number,
    phaseActive: boolean
  ) => {
    if (entity.collected) return;

    const hs = entity.size / 2;
    const { x, y, z } = entity.position;

    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt, pitch);
    if (!projC) return;

    const dist = projC.dist;
    if (dist > FOG_DISTANCE) return; 

    // Vertices
    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, 
      ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, 
      fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, 
      btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, 
      bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };

    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt, pitch),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt, pitch),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt, pitch),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt, pitch),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt, pitch),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt, pitch),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt, pitch),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt, pitch),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;

    if (z - hs > camZ + 0.1) {
       drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    }

    // Side
    if (x < camX) {
        if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive);
    } else {
        if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive);
    }

    // Top / Bottom
    if (y < camY) {
         drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
    }
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) scoreRef.current.innerText = `SCORE: ${state.score} / 250`;
    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;
    if (livesRef.current) {
        let hearts = '';
        for(let i=0; i<state.lives; i++) hearts += '❤️';
        livesRef.current.innerText = hearts;
    }

    if (abilitiesRef.current) {
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const phaseRemaining = Math.ceil(state.player.phaseTimeRemaining / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = '';
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH${state.player.phaseActive ? `<div class="absolute inset-0 flex items-center justify-center text-cyan-200 text-sm">${phaseRemaining}</div>` : ''}${!state.player.phaseActive && phaseCD > 0 ? `<div class="absolute inset-0 flex items-center justify-center bg-black/60 text-white text-sm">${phaseCD}</div>` : ''}</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.lives <= 0 || state.gameWon) {
      onGameOver(state.score);
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) {
         skyGrad.addColorStop(0, '#004455');
         skyGrad.addColorStop(1, '#0088AA');
    } else {
         skyGrad.addColorStop(0, '#4ea7d6');
         skyGrad.addColorStop(1, '#87CEEB');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera Configuration (High-Angle / Top-Down view)
    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);

    // Increased Y height and angled pitch down for "from above" view
    let camX = state.player.position.x * 0.8; 
    let camY = state.player.position.y + 7.5 + bob; 
    let camZ = state.player.position.z - 5.5; 
    const tilt = state.player.tilt;
    const pitch = 0.6; // ~35 degrees looking down

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities: Far to Near (Painter's Algorithm)
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);

    // Helper to check if item is behind camera
    const isVisible = (z: number) => z > camZ + 0.5;

    let steveDrawn = false;

    // Render Bots & Entities Mixed
    const allDrawables = [
        ...sortedEntities.map(e => ({ type: 'ENTITY', z: e.position.z, obj: e })),
        { type: 'PLAYER', z: state.player.position.z, obj: state.player },
        ...(state.isMultiplayer ? state.otherPlayers.map(p => ({ type: 'BOT', z: p.position.z, obj: p })) : [])
    ].sort((a, b) => b.z - a.z); // Draw furthest first

    for (const item of allDrawables) {
        if (!isVisible(item.z)) continue;

        if (item.type === 'ENTITY') {
            const e = item.obj as Entity;
            drawCube(ctx, e, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive);
        } else if (item.type === 'PLAYER') {
            drawSteve(ctx, state.player.position, camX, camY, camZ, tilt, pitch, width, height, state.player.phaseActive, time, state.player.isJumping);
        } else if (item.type === 'BOT') {
            const bot = item.obj as any;
            drawSteve(ctx, bot.position, camX, camY, camZ, tilt, pitch, width, height, false, time + parseInt(bot.id.split('_')[1])*500, bot.isJumping, bot.colors);

            // Draw Name Tag
            const headPos = { x: bot.position.x, y: bot.position.y + 1.8, z: bot.position.z };
            const p = project(headPos, camX, camY, camZ, width, height, tilt, pitch);
            if (p) {
                ctx.fillStyle = 'rgba(0,0,0,0.5)';
                const textWidth = ctx.measureText(bot.name).width;
                ctx.fillRect(p.x - 20, p.y - 15, 40, 15);
                ctx.fillStyle = '#FFFFFF';
                ctx.font = '10px monospace';
                ctx.textAlign = 'center';
                ctx.fillText(bot.name, p.x, p.y - 4);
            }
        }
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, tilt, pitch);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len);
        ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => {
        if(canvasRef.current) {
            canvasRef.current.width = window.innerWidth;
            canvasRef.current.height = window.innerHeight;
        }
    };
    window.addEventListener('resize', handleResize);
    handleResize();

    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
