                  <BlockPreview type={BlockType.GOLD} label="Gold Block" desc="Collect to LEVEL UP! (+10 pts)" />
                  <BlockPreview type={BlockType.TNT} label="TNT" desc="EXPLOSIVE! Avoid at all costs." />
