      {/* Game Over Screen */}
      {appState === AppState.GAME_OVER && (
        <div className={`z-20 text-center p-8 backdrop-blur-sm border-4 rounded-lg shadow-[0_0_30px_rgba(0,0,0,0.5)] min-w-[300px] ${finalScore >= 250 ? 'bg-green-900/80 border-green-500 shadow-[0_0_30px_rgba(0,255,0,0.5)]' : 'bg-red-900/80 border-red-600 shadow-[0_0_30px_rgba(255,0,0,0.5)]'}`}>
          <h2 className={`text-5xl mb-2 font-bold ${finalScore >= 250 ? 'text-green-200' : 'text-red-200'}`}>
            {finalScore >= 250 ? 'YOU WIN!' : 'GAME OVER'}
          </h2>
          <div className="text-xl text-white mb-6">
            {finalScore >= 250 ? 'Great job' : 'Better luck next time'}
          </div>
          <div className="text-4xl text-yellow-400 mb-8 font-mono border-2 border-yellow-600 p-4 bg-black/30 rounded inline-block">Score: {finalScore}</div>

          <div className="flex gap-4 justify-center">
            <button 
              onClick={() => startGame(false)}
              className="px-8 py-4 bg-gray-100 hover:bg-white text-black text-xl font-bold border-b-4 border-gray-400 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              TRY AGAIN
            </button>
            <button 
              onClick={() => setAppState(AppState.MENU)}
              className="px-8 py-4 bg-black/50 hover:bg-black/40 text-white text-xl font-bold border-b-4 border-black/70 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              MENU
            </button>
          </div>
        </div>
      )}

      {/* Background decoration for menu */}
      {appState !== AppState.PLAYING && (
         <div className="absolute inset-0 -z-10 overflow-hidden opacity-30">
            <div className="absolute w-full h-full bg-[linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111),linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111)] bg-[length:40px_40px] bg-[position:0_0,20px_20px] bg-neutral-800" />
         </div>
      )}
    </div>
  );
}

import React, { useEffect, useRef, useCallback } from 'react';
import { GameEngine, InputMap } from '../services/engine';
import { COLORS, SKY_COLOR_HEX, hexToRgb, FOG_DISTANCE } from '../constants';
import { Entity, BlockType, Point3D } from '../types';

interface GameCanvasProps {
  engine: GameEngine;
  onGameOver: (scores: { p1: number, p2: number | null }) => void;
  inputState: { current: InputMap };
  inputStateP2?: { current: InputMap };
}

const FOV = 450;
const SKY_RGB = hexToRgb(SKY_COLOR_HEX);

export const GameCanvas: React.FC<GameCanvasProps> = ({ engine, onGameOver, inputState, inputStateP2 }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const scoreRef = useRef<HTMLDivElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  const goldRef = useRef<HTMLDivElement>(null);
  const livesRef = useRef<HTMLDivElement>(null);
  const abilitiesRef = useRef<HTMLDivElement>(null);

  // --- Helpers ---

  const lerp = (start: number, end: number, t: number) => start * (1 - t) + end * t;

  const applyFog = useCallback((colorHex: string, distance: number) => {
    const rgb = hexToRgb(colorHex);
    let fogFactor = Math.max(0, Math.min(1, (distance - 5) / (FOG_DISTANCE - 10)));
    fogFactor = fogFactor * fogFactor;

    const r = Math.round(lerp(rgb.r, SKY_RGB.r, fogFactor));
    const g = Math.round(lerp(rgb.g, SKY_RGB.g, fogFactor));
    const b = Math.round(lerp(rgb.b, SKY_RGB.b, fogFactor));

    return `rgb(${r},${g},${b})`;
  }, []);

  const project = useCallback((p: Point3D, camX: number, camY: number, camZ: number, width: number, height: number, tilt: number, pitch: number) => {
    // 1. Translate
    let rx = p.x - camX;
    let ry = p.y - camY;
    let rz = p.z - camZ;

    // 2. Rotate (Tilt - Z roll)
    if (tilt !== 0) {
        const cos = Math.cos(tilt);
        const sin = Math.sin(tilt);
        const nx = rx * cos - ry * sin;
        const ny = rx * sin + ry * cos;
        rx = nx;
        ry = ny;
    }

    // 3. Rotate (Pitch - X axis)
    if (pitch !== 0) {
        const cos = Math.cos(pitch);
        const sin = Math.sin(pitch);
        const ny = ry * cos + rz * sin;
        const nz = -ry * sin + rz * cos;
        ry = ny;
        rz = nz;
    }

    if (rz <= 0.1) return null;

    // 4. Project
    const scale = FOV / rz;
    const x2d = (rx * scale) + (width / 2);
    const y2d = (height / 2) - (ry * scale);

    return { x: x2d, y: y2d, scale, dist: rz };
  }, []);

  // --- Drawing Primitives ---

  const drawQuad = (ctx: CanvasRenderingContext2D, p1: any, p2: any, p3: any, p4: any, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.lineTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.closePath();
    ctx.fill();
  };

  // --- Steve Drawing ---
  const drawStevePart = (
      ctx: CanvasRenderingContext2D,
      p: Point3D, // Center position
      size: { w: number, h: number, d: number },
      colors: { front: string, back: string, top: string, bottom: string, left: string, right: string },
      rotation: { x: number, y: number, z: number },
      partType: 'HEAD' | 'TORSO' | 'ARM' | 'LEG',
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean
  ) => {
      const hw = size.w / 2;
      const hh = size.h / 2;
      const hd = size.d / 2;

      // Local vertices
      const verts = [
          { x: -hw, y: hh, z: -hd }, { x: hw, y: hh, z: -hd }, { x: hw, y: -hh, z: -hd }, { x: -hw, y: -hh, z: -hd }, // Front
          { x: -hw, y: hh, z: hd },  { x: hw, y: hh, z: hd },  { x: hw, y: -hh, z: hd },  { x: -hw, y: -hh, z: hd }   // Back
      ];

      // Rotate and Translate
      const worldVerts = verts.map(v => {
          // X Rotation (Pitch)
          let y1 = v.y * Math.cos(rotation.x) - v.z * Math.sin(rotation.x);
          let z1 = v.y * Math.sin(rotation.x) + v.z * Math.cos(rotation.x);

          // Z Rotation (Roll)
          let x2 = v.x * Math.cos(rotation.z) - y1 * Math.sin(rotation.z);
          let y2 = v.x * Math.sin(rotation.z) + y1 * Math.cos(rotation.z);

          // Translate
          return {
              x: x2 + p.x,
              y: y2 + p.y,
              z: z1 + p.z
          };
      });

      // Project
      const projVerts = worldVerts.map(v => project(v, camX, camY, camZ, width, height, tilt, pitch));

      // Calculate Center Dist for Fog
      const dist = Math.sqrt(Math.pow(p.x - camX, 2) + Math.pow(p.y - camY, 2) + Math.pow(p.z - camZ, 2));

      if (phaseActive) ctx.globalAlpha = 0.6;

      const drawFace = (idxs: number[], color: string, normal: 'FRONT' | 'BACK' | 'TOP' | 'BOTTOM' | 'LEFT' | 'RIGHT') => {
          if (idxs.some(i => !projVerts[i])) return;
          const ps = idxs.map(i => projVerts[i]!);

          // Simple normal check (cross product z)
          const v1 = { x: ps[1].x - ps[0].x, y: ps[1].y - ps[0].y };
          const v2 = { x: ps[2].x - ps[1].x, y: ps[2].y - ps[1].y };
          const cross = v1.x * v2.y - v1.y * v2.x;

          if (cross > 0) return; // Backface culling

          drawQuad(ctx, ps[0], ps[1], ps[2], ps[3], applyFog(color, dist));

          // --- DETAILS ---
          const mapUV = (u: number, v: number) => {
            const topX = lerp(ps[0].x, ps[1].x, u); const topY = lerp(ps[0].y, ps[1].y, u);
            const botX = lerp(ps[3].x, ps[2].x, u); const botY = lerp(ps[3].y, ps[2].y, u);
            return { x: lerp(topX, botX, v), y: lerp(topY, botY, v) };
          }
          const drawRect = (u: number, v: number, w: number, h: number, c: string) => {
             const tl = mapUV(u, v);
             const tr = mapUV(u+w, v);
             const br = mapUV(u+w, v+h);
             const bl = mapUV(u, v+h);
             drawQuad(ctx, tl, tr, br, bl, applyFog(c, dist));
          }

          // FACE
          if (partType === 'HEAD' && normal === 'FRONT') {
             // Hair
             drawRect(0, 0, 1, 0.25, '#2A1D13');
             // Eyes
             drawRect(0.125, 0.5, 0.125, 0.125, '#FFFFFF'); // L Sclera
             drawRect(0.25, 0.5, 0.125, 0.125, '#493C7B'); // L Pupil
             drawRect(0.625, 0.5, 0.125, 0.125, '#FFFFFF'); // R Sclera
             drawRect(0.75, 0.5, 0.125, 0.125, '#493C7B'); // R Pupil
             // Nose
             drawRect(0.4375, 0.625, 0.125, 0.0625, '#A57356');
             // Mouth/Beard
             drawRect(0.375, 0.75, 0.25, 0.125, '#784732');
          }
          // SIDE HAIR
          if (partType === 'HEAD' && (normal === 'LEFT' || normal === 'RIGHT' || normal === 'BACK')) {
              drawRect(0, 0, 1, 0.25, '#2A1D13');
          }

          // SLEEVES
          if (partType === 'ARM' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0, 1, 0.35, colors.front); // Use shirt color
          }

          // SHOES
          if (partType === 'LEG' && normal !== 'TOP' && normal !== 'BOTTOM') {
              drawRect(0, 0.85, 1, 0.15, '#555555');
          }
      };

      // Indices for CCW winding
      drawFace([0,1,2,3], colors.front, 'FRONT');
      drawFace([5,4,7,6], colors.back, 'BACK');
      drawFace([4,5,1,0], colors.top, 'TOP');
      drawFace([3,2,6,7], colors.bottom, 'BOTTOM');
      drawFace([4,0,3,7], colors.left, 'LEFT');
      drawFace([1,5,6,2], colors.right, 'RIGHT');

      ctx.globalAlpha = 1.0;
  };

  const drawSteve = (
      ctx: CanvasRenderingContext2D,
      pos: Point3D,
      camX: number, camY: number, camZ: number, tilt: number, pitch: number,
      width: number, height: number,
      phaseActive: boolean,
      time: number,
      isJumping: boolean,
      customColors: { shirt: string, pants: string } = { shirt: '#00AAAA', pants: '#3B3696' }
  ) => {
      // Animation Config
      const runFreq = 0.0175; 
      const runAmp = 1.2; 
      const animPhase = time * runFreq;
      const swing = Math.sin(animPhase) * runAmp; 
      const bob = isJumping ? 0 : Math.abs(Math.sin(animPhase)) * 0.1;
      const steveY = pos.y + bob;

      // Steve Colors
      const skinColor = '#E3A581'; // Lighter, rosier skin
      const shirtColor = customColors.shirt;
      const pantsColor = customColors.pants;
      const hairColor = '#2A1D13'; // Dark Brown

      // Dimensions
      const legW = 0.22; const legH = 0.7; const legD = 0.22;
      const torsoW = 0.5; const torsoH = 0.65; const torsoD = 0.25;
      const headS = 0.45;
      const armW = 0.2; const armH = 0.7; const armD = 0.22;

      const hipY = steveY + legH;
      const shoulderY = hipY + torsoH;
      const neckY = shoulderY;

      const leftLegRot = -swing; const rightLegRot = swing;
      const leftArmRot = swing; const rightArmRot = -swing; 

      // Draw Parts
      drawStevePart(ctx, { x: pos.x - 0.13, y: steveY + legH/2, z: pos.z }, { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: leftLegRot, y: 0, z: 0 }, 'LEG', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
      drawStevePart(ctx, { x: pos.x + 0.13, y: steveY + legH/2, z: pos.z }, { w: legW, h: legH, d: legD }, 
          { front: pantsColor, back: pantsColor, top: pantsColor, bottom: pantsColor, left: pantsColor, right: pantsColor },
          { x: rightLegRot, y: 0, z: 0 }, 'LEG', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
      drawStevePart(ctx, { x: pos.x, y: hipY + torsoH/2, z: pos.z }, { w: torsoW, h: torsoH, d: torsoD }, 
          { front: shirtColor, back: shirtColor, top: shirtColor, bottom: shirtColor, left: shirtColor, right: shirtColor },
          { x: 0, y: 0, z: 0 }, 'TORSO', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
      drawStevePart(ctx, { x: pos.x, y: neckY + headS/2, z: pos.z }, { w: headS, h: headS, d: headS }, 
          { front: skinColor, back: hairColor, top: hairColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: 0, y: 0, z: 0 }, 'HEAD', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
      drawStevePart(ctx, { x: pos.x - 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: leftArmRot, y: 0, z: 0 }, 'ARM', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
      drawStevePart(ctx, { x: pos.x + 0.36, y: shoulderY - armH/2 + 0.1, z: pos.z }, { w: armW, h: armH, d: armD }, 
          { front: skinColor, back: skinColor, top: shirtColor, bottom: skinColor, left: skinColor, right: skinColor },
          { x: rightArmRot, y: 0, z: 0 }, 'ARM', camX, camY, camZ, tilt, pitch, width, height, phaseActive);
  }

  // --- World Drawing ---
  const drawFaceDetails = (ctx: CanvasRenderingContext2D, type: BlockType, face: 'TOP' | 'SIDE' | 'FRONT', p1: any, p2: any, p3: any, p4: any, dist: number, phaseActive: boolean) => {
    const baseColor = COLORS[type];
    const colorKey = face === 'TOP' ? 'top' : (face === 'SIDE' ? 'side' : 'front');
    const color = applyFog(baseColor[colorKey], dist);
    if (phaseActive && type !== BlockType.GOLD) ctx.globalAlpha = 0.5;

    drawQuad(ctx, p1, p2, p3, p4, color);

    if (type === BlockType.TNT && face !== 'TOP') {
        const bandColor = applyFog('#FFFFFF', dist);
        const topH = 0.33; const botH = 0.66;
        const tl_w = { x: lerp(p1.x, p4.x, topH), y: lerp(p1.y, p4.y, topH) };
        const tr_w = { x: lerp(p2.x, p3.x, topH), y: lerp(p2.y, p3.y, topH) };
        const bl_w = { x: lerp(p1.x, p4.x, botH), y: lerp(p1.y, p4.y, botH) };
        const br_w = { x: lerp(p2.x, p3.x, botH), y: lerp(p2.y, p3.y, botH) };
        drawQuad(ctx, tl_w, tr_w, br_w, bl_w, bandColor);
    }
    // ... (Keep existing simple detail logic for space) ...
    // Basic wireframe
    ctx.strokeStyle = `rgba(0,0,0,${Math.max(0, 0.1 - dist/100)})`;
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.globalAlpha = 1.0; 
  };

  const drawCube = useCallback((ctx: CanvasRenderingContext2D, entity: Entity, camX: number, camY: number, camZ: number, tilt: number, pitch: number, width: number, height: number, phaseActive: boolean) => {
    if (entity.collected) return;
    const hs = entity.size / 2;
    const { x, y, z } = entity.position;
    const projC = project({x, y, z}, camX, camY, camZ, width, height, tilt, pitch);
    if (!projC || projC.dist > FOG_DISTANCE) return;
    const dist = projC.dist;

    const v = {
      ft: {x: x - hs, y: y + hs, z: z - hs}, ftr: {x: x + hs, y: y + hs, z: z - hs}, 
      fb: {x: x - hs, y: y - hs, z: z - hs}, fbr: {x: x + hs, y: y - hs, z: z - hs}, 
      bt: {x: x - hs, y: y + hs, z: z + hs}, btr: {x: x + hs, y: y + hs, z: z + hs}, 
      bb: {x: x - hs, y: y - hs, z: z + hs}, bbr: {x: x + hs, y: y - hs, z: z + hs}, 
    };
    const p = {
        ft: project(v.ft, camX, camY, camZ, width, height, tilt, pitch),
        ftr: project(v.ftr, camX, camY, camZ, width, height, tilt, pitch),
        fb: project(v.fb, camX, camY, camZ, width, height, tilt, pitch),
        fbr: project(v.fbr, camX, camY, camZ, width, height, tilt, pitch),
        bt: project(v.bt, camX, camY, camZ, width, height, tilt, pitch),
        btr: project(v.btr, camX, camY, camZ, width, height, tilt, pitch),
        bb: project(v.bb, camX, camY, camZ, width, height, tilt, pitch),
        bbr: project(v.bbr, camX, camY, camZ, width, height, tilt, pitch),
    };

    if (!p.ft || !p.ftr || !p.fb || !p.fbr || !p.bt || !p.btr) return;
    if (z - hs > camZ + 0.1) drawFaceDetails(ctx, entity.type, 'FRONT', p.ft, p.ftr, p.fbr, p.fb, dist, phaseActive);
    if (x < camX) { if (p.bbr) drawFaceDetails(ctx, entity.type, 'SIDE', p.ftr, p.btr, p.bbr, p.fbr, dist, phaseActive); } 
    else { if (p.bb) drawFaceDetails(ctx, entity.type, 'SIDE', p.bt, p.ft, p.fb, p.bb, dist, phaseActive); }
    if (y < camY) drawFaceDetails(ctx, entity.type, 'TOP', p.bt, p.btr, p.ftr, p.ft, dist, phaseActive);
  }, [project, applyFog]);

  const loop = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    engine.update(inputState.current, inputStateP2?.current || { left: false, right: false, jump: false }, 16);
    const state = engine.getState();

    // UI Updates
    if (scoreRef.current) {
        if (state.player2) {
            scoreRef.current.innerText = `P1: ${state.player.score}  P2: ${state.player2.score}`;
        } else {
            scoreRef.current.innerText = `SCORE: ${state.player.score}`;
        }
    }

    if (levelRef.current) levelRef.current.innerText = `LEVEL: ${state.level}`;
    if (goldRef.current) goldRef.current.innerText = `GOLD: ${state.goldCollected} / ${state.levelTarget}`;

    // Lives UI for P1 and P2
    if (livesRef.current) {
        const getHearts = (lives: number) => {
            let h = '';
            for(let i=0; i<lives; i++) h += '❤️';
            return h;
        }
        let html = `<div class="text-green-300">P1: ${getHearts(state.player.lives)}</div>`;
        if (state.player2) {
            html += `<div class="text-red-400">P2: ${getHearts(state.player2.lives)}</div>`;
        }
        livesRef.current.innerHTML = html;
    }

    // Abilities UI (P1 Only shown for simplicity or both?)
    if (abilitiesRef.current) {
        // Just showing P1 abilities for now in the HUD to avoid clutter
        const phaseCD = Math.ceil(state.player.phaseCooldown / 1000);
        const jumpAvailable = state.player.jumpCount < 2;
        let html = `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${jumpAvailable ? 'border-green-400 bg-green-900/50' : 'border-gray-500 bg-gray-900/50'} flex items-center justify-center text-xs font-bold relative">DJ</div><span class="text-[10px] mt-1 text-gray-400">JUMP</span></div>`;
        html += `<div class="flex flex-col items-center"><div class="w-10 h-10 border-2 ${state.player.phaseActive ? 'border-cyan-400 bg-cyan-900/50 animate-pulse' : (phaseCD <= 0 ? 'border-green-400 bg-green-900/50' : 'border-red-400 bg-red-900/50')} flex items-center justify-center text-xs font-bold relative">PH</div><span class="text-[10px] mt-1 text-gray-400">"B"</span></div>`;
        abilitiesRef.current.innerHTML = html;
    }

    if (state.gameOver || state.gameWon) {
      onGameOver({ 
          p1: state.player.score, 
          p2: state.player2 ? state.player2.score : null 
      });
      return; 
    }

    const width = canvas.width;
    const height = canvas.height;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
    if (state.player.phaseActive) { skyGrad.addColorStop(0, '#004455'); skyGrad.addColorStop(1, '#0088AA'); } 
    else { skyGrad.addColorStop(0, '#4ea7d6'); skyGrad.addColorStop(1, '#87CEEB'); }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, width, height);

    // Camera Logic: Average position of active players
    let camX = state.player.position.x;
    let camZ = state.player.position.z;
    if (state.player2 && state.player2.lives > 0) {
        if (state.player.lives > 0) {
             camX = (state.player.position.x + state.player2.position.x) / 2;
             camZ = (state.player.position.z + state.player2.position.z) / 2;
        } else {
             camX = state.player2.position.x;
             camZ = state.player2.position.z;
        }
    } else if (state.player.lives <= 0 && state.player2) {
        // P1 dead, P2 alive
        camX = state.player2.position.x;
        camZ = state.player2.position.z;
    }

    const bob = Math.sin(time * 0.015) * 0.05 * (state.speed / 0.5);
    camX = camX * 0.8;
    let camY = 7.5 + bob;
    camZ = camZ - 5.5;
    const tilt = state.player.tilt; // Use P1 tilt for now or average? Let's use 0 for stable shared cam
    const pitch = 0.6; 

    if (state.shakeIntensity > 0) {
       camX += (Math.random() - 0.5) * state.shakeIntensity;
       camY += (Math.random() - 0.5) * state.shakeIntensity;
    }

    // Sort Entities
    const sortedEntities = [...state.entities].sort((a, b) => b.position.z - a.position.z);
    const isVisible = (z: number) => z > camZ + 0.5;

    // Draw List
    const playersToDraw = [];
    if (state.player.lives > 0) playersToDraw.push({ type: 'PLAYER', z: state.player.position.z, obj: state.player, isP2: false });
    if (state.player2 && state.player2.lives > 0) playersToDraw.push({ type: 'PLAYER', z: state.player2.position.z, obj: state.player2, isP2: true });

    const allDrawables = [
        ...sortedEntities.map(e => ({ type: 'ENTITY', z: e.position.z, obj: e })),
        ...playersToDraw
    ].sort((a, b) => b.z - a.z);

    for (const item of allDrawables) {
        if (!isVisible(item.z)) continue;
        if (item.type === 'ENTITY') {
            const e = item.obj as Entity;
            drawCube(ctx, e, camX, camY, camZ, 0, pitch, width, height, state.player.phaseActive); // Disabled tilt for MP stability
        } else if (item.type === 'PLAYER') {
            const p = item.obj as any;
            // Name Tag
            const headPos = { x: p.position.x, y: p.position.y + 1.8, z: p.position.z };
            const proj = project(headPos, camX, camY, camZ, width, height, 0, pitch);

            drawSteve(ctx, p.position, camX, camY, camZ, 0, pitch, width, height, p.phaseActive, time, p.isJumping, p.colors);

            if (proj) {
               ctx.fillStyle = 'rgba(0,0,0,0.5)';
               const label = (item as any).isP2 ? "P2" : "P1";
               ctx.fillRect(proj.x - 10, proj.y - 15, 20, 12);
               ctx.fillStyle = (item as any).isP2 ? '#FF5555' : '#00AAAA';
               ctx.font = 'bold 10px monospace';
               ctx.textAlign = 'center';
               ctx.fillText(label, proj.x, proj.y - 5);
            }
        }
    }

    // Particles
    for (const p of state.particles) {
        const proj = project(p.position, camX, camY, camZ, width, height, 0, pitch);
        if (proj) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = p.life;
            const size = proj.scale * p.size;
            ctx.fillRect(proj.x - size/2, proj.y - size/2, size, size);
            ctx.globalAlpha = 1.0;
        }
    }

    // Speed Lines
    if (state.speed > 0.6) {
      ctx.strokeStyle = state.player.phaseActive ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = Math.random() * width; const y = Math.random() * height;
        const len = Math.random() * 50 + 20;
        const cx = width/2; const cy = height/2;
        const angle = Math.atan2(y-cy, x-cx);
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + Math.cos(angle)*len, y + Math.sin(angle)*len); ctx.stroke();
      }
    }

    requestRef.current = requestAnimationFrame(loop);
  }, [engine, inputState, inputStateP2, onGameOver, drawCube, project]);

  useEffect(() => {
    const handleResize = () => { if(canvasRef.current) { canvasRef.current.width = window.innerWidth; canvasRef.current.height = window.innerHeight; } };
    window.addEventListener('resize', handleResize);
    handleResize();
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [loop]);

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full" />
      <div className="absolute top-4 left-4 text-4xl text-white font-bold tracking-widest drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] select-none pointer-events-none flex flex-col gap-2">
         <div ref={scoreRef} className="text-yellow-400">SCORE: 0 / 250</div>
         <div ref={levelRef} className="text-blue-200 text-2xl">LEVEL: 1</div>
         <div ref={goldRef} className="text-yellow-200 text-xl font-mono">GOLD: 0/0</div>
         <div ref={livesRef}></div>
      </div>
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex gap-6 text-white" ref={abilitiesRef}></div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { GameEngine } from './services/engine';
import { COLORS } from './constants';
import { BlockType, Difficulty, HighScore } from './types';
import { audioService } from './services/audio';

enum AppState {
  MENU,
  HELP,
  PLAYING,
  GAME_OVER
}

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.MENU);
  const [finalScores, setFinalScores] = useState<{p1: number, p2: number | null}>({p1: 0, p2: null});
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
  const [playerName, setPlayerName] = useState('Player');
  const [highScores, setHighScores] = useState<HighScore[]>([]);
  const engineRef = useRef<GameEngine>(new GameEngine());

  const inputStateP1 = useRef({
    left: false,
    right: false,
    jump: false,
    phase: false
  });

  const inputStateP2 = useRef({
    left: false,
    right: false,
    jump: false,
    phase: false,
    forward: false // W
  });

  // Load High Scores
  useEffect(() => {
    const stored = localStorage.getItem('blockyRunnerHighScores');
    if (stored) {
      setHighScores(JSON.parse(stored));
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (appState !== AppState.PLAYING) return;

      // P1 Controls (Arrows + Space/Enter)
      switch(e.code) {
        case 'ArrowLeft':
          inputStateP1.current.left = true;
          break;
        case 'ArrowRight':
          inputStateP1.current.right = true;
          break;
        case 'Space':
        case 'ArrowUp':
          inputStateP1.current.jump = true;
          break;
        case 'KeyB':
        case 'Enter':
          inputStateP1.current.phase = true;
          break;

        // P2 Controls (WASD + V + Ctrl)
        case 'KeyA':
          inputStateP2.current.left = true;
          break;
        case 'KeyD':
          inputStateP2.current.right = true;
          break;
        case 'KeyW':
          inputStateP2.current.forward = true;
          break;
        case 'KeyV':
          inputStateP2.current.jump = true;
          break;
        case 'ControlLeft':
        case 'ControlRight':
          inputStateP2.current.phase = true;
          break;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      switch(e.code) {
        // P1
        case 'ArrowLeft':
          inputStateP1.current.left = false;
          break;
        case 'ArrowRight':
          inputStateP1.current.right = false;
          break;
        case 'Space':
        case 'ArrowUp':
          inputStateP1.current.jump = false;
          break;
        case 'KeyB':
        case 'Enter':
          inputStateP1.current.phase = false;
          break;

        // P2
        case 'KeyA':
          inputStateP2.current.left = false;
          break;
        case 'KeyD':
          inputStateP2.current.right = false;
          break;
        case 'KeyW':
          inputStateP2.current.forward = false;
          break;
        case 'KeyV':
          inputStateP2.current.jump = false;
          break;
        case 'ControlLeft':
        case 'ControlRight':
          inputStateP2.current.phase = false;
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [appState]);

  const startGame = (isMultiplayer: boolean = false) => {
    if (!playerName.trim()) {
        alert("Please enter your name!");
        return;
    }
    audioService.initialize();
    engineRef.current.reset(selectedDifficulty, isMultiplayer);
    // Reset inputs
    inputStateP1.current = { left: false, right: false, jump: false, phase: false };
    inputStateP2.current = { left: false, right: false, jump: false, phase: false, forward: false };
    setAppState(AppState.PLAYING);
  };

  const handleGameOver = (scores: {p1: number, p2: number | null}) => {
    setFinalScores(scores);

    // Save High Score (Best score of the run)
    const bestScore = scores.p2 !== null ? Math.max(scores.p1, scores.p2) : scores.p1;
    let name = playerName;
    if (scores.p2 !== null && scores.p2 > scores.p1) {
        name = "Player 2";
    }

    const newScore: HighScore = {
      name: name,
      score: bestScore,
      difficulty: selectedDifficulty,
      date: new Date().toLocaleDateString()
    };

    const newScores = [...highScores, newScore].sort((a, b) => b.score - a.score).slice(0, 5); // Keep top 5
    setHighScores(newScores);
    localStorage.setItem('blockyRunnerHighScores', JSON.stringify(newScores));

    // Win logic based on collective score for sound, but display individual
    const totalScore = scores.p1 + (scores.p2 || 0);
    if (totalScore >= 250) { // Using accumulated logic from engine
      audioService.playWin();
    } else {
      audioService.playGameOver();
    }
    setAppState(AppState.GAME_OVER);
  };

  const BlockPreview = ({ type, label, desc }: { type: BlockType, label: string, desc: string }) => {
     const color = COLORS[type];
     return (
       <div className="flex items-center gap-4 mb-4">
          <div className="w-12 h-12 relative transform rotate-6 hover:rotate-12 transition-transform shadow-lg border-2 border-black/20 shrink-0" 
               style={{ backgroundColor: color.front, boxShadow: `4px 4px 0px ${color.side}` }}>
               <div className="absolute top-0 w-full h-1/3" style={{ backgroundColor: color.top }}></div>
               {type === BlockType.TNT && <div className="absolute top-1/3 w-full h-1/3 bg-white/90 text-[8px] flex items-center justify-center font-bold text-black">TNT</div>}
               {type === BlockType.CREEPER && <div className="absolute inset-0 flex items-center justify-center text-black font-bold text-xs">:(</div>}
               {type === BlockType.GOLD && <div className="absolute inset-0 flex items-center justify-center"><div className="w-2 h-2 bg-white/50 rounded-full"></div></div>}
          </div>
          <div className="text-left">
            <div className="font-bold text-lg text-white">{label}</div>
            <div className="text-sm text-gray-300 leading-tight">{desc}</div>
          </div>
       </div>
     )
  };

  // Helper for touch input P1
  const setInputP1 = (key: keyof typeof inputStateP1.current, value: boolean) => {
    inputStateP1.current[key] = value;
  };
  // Helper for touch input P2
  const setInputP2 = (key: keyof typeof inputStateP2.current, value: boolean) => {
     // @ts-ignore
    inputStateP2.current[key] = value;
  };

  return (
    <div className="w-full h-screen bg-neutral-900 flex flex-col items-center justify-center relative overflow-hidden touch-none select-none">

      {/* Menu Screen */}
      {appState === AppState.MENU && (
        <div className="z-20 text-center p-10 bg-black/60 backdrop-blur-sm border-4 border-green-600 rounded-lg shadow-[0_0_20px_rgba(0,255,0,0.5)] max-w-lg w-full max-h-screen overflow-y-auto">
          <h1 className="text-6xl mb-2 text-green-400 font-bold tracking-tighter drop-shadow-md">BLOCKY RUNNER</h1>
          <p className="text-xl text-gray-300 mb-6 font-mono">Run fast. Collect Gold. Survive.</p>

          <div className="mb-6 flex flex-col items-center">
             <label className="text-sm text-green-300 mb-1 font-bold">PLAYER NAME</label>
             <input 
                type="text" 
                value={playerName} 
                onChange={(e) => setPlayerName(e.target.value)}
                maxLength={10}
                className="bg-black/50 border-2 border-green-600 text-white text-center text-xl p-2 rounded w-48 focus:outline-none focus:border-green-400 font-mono uppercase"
             />
          </div>

          <div className="mb-8">
            <div className="text-white text-lg mb-2 font-bold">SELECT DIFFICULTY</div>
            <div className="flex gap-2 justify-center">
              {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map((diff) => (
                <button
                  key={diff}
                  onClick={() => setSelectedDifficulty(diff)}
                  className={`px-4 py-2 border-b-4 font-bold transition-all text-sm ${
                    selectedDifficulty === diff 
                      ? 'bg-yellow-500 text-black border-yellow-700 -translate-y-1' 
                      : 'bg-gray-700 text-gray-300 border-gray-900 hover:bg-gray-600'
                  }`}
                >
                  {diff}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <button 
              onClick={() => startGame(false)}
              className="px-8 py-4 bg-green-600 hover:bg-green-500 text-white text-2xl font-bold border-b-4 border-green-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              START RUN (1 Player)
            </button>
             <button 
              onClick={() => startGame(true)}
              className="px-8 py-4 bg-purple-600 hover:bg-purple-500 text-white text-xl font-bold border-b-4 border-purple-800 active:border-b-0 active:translate-y-1 transition-all rounded flex items-center justify-center gap-2"
            >
              2 PLAYERS (Local)
            </button>
            <button 
              onClick={() => setAppState(AppState.HELP)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white text-xl font-bold border-b-4 border-blue-800 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              HOW TO PLAY
            </button>
          </div>

          {highScores.length > 0 && (
             <div className="mt-8 bg-black/40 p-4 rounded border border-white/10">
                <h3 className="text-yellow-400 font-bold mb-2 border-b border-white/20 pb-1">TOP SCORES</h3>
                <div className="text-sm font-mono space-y-1">
                   {highScores.map((score, idx) => (
                       <div key={idx} className="flex justify-between text-gray-300">
                          <span>{idx+1}. {score.name}</span>
                          <span className="text-white">{score.score}</span>
                       </div>
                   ))}
                </div>
             </div>
          )}
        </div>
      )}

      {/* Help Screen */}
      {appState === AppState.HELP && (
        <div className="z-20 p-8 bg-black/80 backdrop-blur-md border-4 border-blue-500 rounded-lg shadow-[0_0_20px_rgba(59,130,246,0.5)] max-w-4xl w-full text-white overflow-hidden max-h-[90vh] flex flex-col">
          <h2 className="text-4xl text-blue-400 mb-6 font-bold text-center border-b-2 border-blue-500/30 pb-4 shrink-0">HOW TO PLAY</h2>

          <div className="grid grid-cols-2 gap-8 overflow-y-auto pr-2">
            <div>
              <h3 className="text-xl text-yellow-400 mb-4 font-bold uppercase tracking-wider sticky top-0 bg-black/80 p-2 z-10">Controls</h3>

              <div className="mb-4">
                  <h4 className="text-green-400 font-bold mb-2">PLAYER 1</h4>
                  <div className="space-y-2 font-mono text-lg">
                    <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">←</span> / <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">→</span> 
                      <span>Move</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 px-4 rounded border-b-4 border-gray-900">SPACE</span> 
                      <span>Jump / Double Jump</span>
                    </div>
                     <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 px-4 rounded border-b-4 border-gray-900">B</span> 
                      <span>Phase</span>
                    </div>
                  </div>
              </div>

              <div>
                  <h4 className="text-red-400 font-bold mb-2">PLAYER 2</h4>
                  <div className="space-y-2 font-mono text-lg">
                    <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">A</span> / <span className="bg-gray-700 p-2 rounded border-b-4 border-gray-900">D</span> 
                      <span>Move</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 px-4 rounded border-b-4 border-gray-900">V</span> 
                      <span>Jump / Double Jump</span>
                    </div>
                     <div className="flex items-center gap-3">
                      <span className="bg-gray-700 p-2 px-4 rounded border-b-4 border-gray-900">CTRL</span> 
                      <span>Phase</span>
                    </div>
                  </div>
              </div>
            </div>

            <div>
              <h3 className="text-xl text-yellow-400 mb-4 font-bold uppercase tracking-wider sticky top-0 bg-black/80 p-2 z-10">Items</h3>
              <div className="grid grid-cols-1 gap-1">
                  <BlockPreview type={BlockType.GOLD} label="Gold Block" desc="Collect to LEVEL UP! (+10 pts)" />
                  <BlockPreview type={BlockType.TNT} label="TNT" desc="EXPLOSIVE! Avoid at all costs." />
                  <BlockPreview type={BlockType.STONE} label="Stone" desc="Basic obstacle. Do not hit." />
              </div>
            </div>
          </div>

          <button 
            onClick={() => setAppState(AppState.MENU)}
            className="mt-8 w-full py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded border-b-4 border-gray-900 active:border-b-0 active:translate-y-1 transition-all shrink-0"
          >
            BACK TO MENU
          </button>
        </div>
      )}

      {/* Game Canvas */}
      {appState === AppState.PLAYING && (
        <>
          <GameCanvas 
            engine={engineRef.current} 
            onGameOver={handleGameOver} 
            inputState={{ current: inputStateP1.current }}
            inputStateP2={{ current: inputStateP2.current }}
          />

          {/* Mobile HUD Controls - Updated for P1 only (Mobile P2 is hard) */}
          <div className="absolute inset-0 pointer-events-none z-30 flex flex-col justify-end p-6 md:p-12 lg:hidden">
            <div className="flex justify-between items-end w-full">
              <div className="flex gap-4 pointer-events-auto">
                <button 
                  className="w-16 h-16 bg-black/40 border-4 border-white/30 rounded active:bg-white/20 active:scale-95 transition-all flex items-center justify-center"
                  onTouchStart={(e) => { e.preventDefault(); setInputP1('left', true); }}
                  onTouchEnd={(e) => { e.preventDefault(); setInputP1('left', false); }}
                  onContextMenu={(e) => e.preventDefault()}
                >
                  <svg viewBox="0 0 24 24" className="w-8 h-8 fill-white"><path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/></svg>
                </button>
                <button 
                  className="w-16 h-16 bg-black/40 border-4 border-white/30 rounded active:bg-white/20 active:scale-95 transition-all flex items-center justify-center"
                  onTouchStart={(e) => { e.preventDefault(); setInputP1('right', true); }}
                  onTouchEnd={(e) => { e.preventDefault(); setInputP1('right', false); }}
                  onContextMenu={(e) => e.preventDefault()}
                >
                  <svg viewBox="0 0 24 24" className="w-8 h-8 fill-white rotate-180"><path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/></svg>
                </button>
              </div>

              <div className="flex flex-col gap-4 items-end pointer-events-auto">
                <button 
                  className="w-16 h-16 bg-cyan-900/40 border-4 border-cyan-400 rounded active:bg-cyan-400/40 active:scale-95 transition-all flex items-center justify-center font-bold text-cyan-200 text-sm"
                  onTouchStart={(e) => { e.preventDefault(); setInputP1('phase', true); }}
                  onTouchEnd={(e) => { e.preventDefault(); setInputP1('phase', false); }}
                  onContextMenu={(e) => e.preventDefault()}
                >
                  PHASE
                </button>
                <button 
                  className="w-24 h-24 bg-black/40 border-4 border-white/30 rounded-full active:bg-white/20 active:scale-95 transition-all flex items-center justify-center font-bold text-white text-lg shadow-lg"
                  onTouchStart={(e) => { e.preventDefault(); setInputP1('jump', true); }}
                  onTouchEnd={(e) => { e.preventDefault(); setInputP1('jump', false); }}
                  onContextMenu={(e) => e.preventDefault()}
                >
                  JUMP
                </button>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Game Over Screen */}
      {appState === AppState.GAME_OVER && (
        <div className={`z-20 text-center p-8 backdrop-blur-sm border-4 rounded-lg shadow-[0_0_30px_rgba(0,0,0,0.5)] min-w-[300px] ${((finalScores.p1 + (finalScores.p2||0)) >= 250) ? 'bg-green-900/80 border-green-500 shadow-[0_0_30px_rgba(0,255,0,0.5)]' : 'bg-red-900/80 border-red-600 shadow-[0_0_30px_rgba(255,0,0,0.5)]'}`}>
          <h2 className={`text-5xl mb-2 font-bold ${((finalScores.p1 + (finalScores.p2||0)) >= 250) ? 'text-green-200' : 'text-red-200'}`}>
            {((finalScores.p1 + (finalScores.p2||0)) >= 250) ? 'YOU WIN!' : 'GAME OVER'}
          </h2>
          <div className="text-xl text-white mb-6">
            {((finalScores.p1 + (finalScores.p2||0)) >= 250) ? 'Great job' : 'Better luck next time'}
          </div>

          <div className="mb-8 font-mono bg-black/30 p-4 rounded border-2 border-yellow-600 inline-block min-w-[200px]">
             {finalScores.p2 !== null ? (
                 <>
                    <div className="text-3xl text-yellow-400 mb-2 border-b border-yellow-600/30 pb-2">SCORES</div>
                    <div className="flex justify-between gap-8 text-2xl">
                        <div className="text-cyan-300">P1: {finalScores.p1}</div>
                        <div className="text-red-400">P2: {finalScores.p2}</div>
                    </div>
                 </>
             ) : (
                 <div className="text-4xl text-yellow-400">Score: {finalScores.p1}</div>
             )}
          </div>

          <div className="flex gap-4 justify-center">
            <button 
              onClick={() => startGame(finalScores.p2 !== null)}
              className="px-8 py-4 bg-gray-100 hover:bg-white text-black text-xl font-bold border-b-4 border-gray-400 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              TRY AGAIN
            </button>
            <button 
              onClick={() => setAppState(AppState.MENU)}
              className="px-8 py-4 bg-black/50 hover:bg-black/40 text-white text-xl font-bold border-b-4 border-black/70 active:border-b-0 active:translate-y-1 transition-all rounded"
            >
              MENU
            </button>
          </div>
        </div>
      )}

      {/* Background decoration for menu */}
      {appState !== AppState.PLAYING && (
         <div className="absolute inset-0 -z-10 overflow-hidden opacity-30">
            <div className="absolute w-full h-full bg-[linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111),linear-gradient(45deg,#111_25%,transparent_25%,transparent_75%,#111_75%,#111)] bg-[length:40px_40px] bg-[position:0_0,20px_20px] bg-neutral-800" />
         </div>
      )}
    </div>
  );
}

